"            int q_row = q_base + half * 8 + i;\n"
"            int q_global = position_start + q_row;\n"
"            if (q_global < k_global) score[i] = -1e30f;\n"
"        }\n"
"        float row_max[8];\n"
"        for (int i = 0; i < 8; i++) {\n"
"            float v = score[i];\n"
"            v = fmaxf(v, __shfl_xor(v, 1, 32));\n"
"            v = fmaxf(v, __shfl_xor(v, 2, 32));\n"
"            v = fmaxf(v, __shfl_xor(v, 4, 32));\n"
"            v = fmaxf(v, __shfl_xor(v, 8, 32));\n"
"            row_max[i] = v;\n"
"        }\n"
"        float alpha[8];\n"
"        for (int i = 0; i < 8; i++) {\n"
"            float new_max = fmaxf(m_i[i], row_max[i]);\n"
"            alpha[i] = __expf(m_i[i] - new_max);\n"
"            float ej = __expf(score[i] - new_max);\n"
"            float s = ej;\n"
"            s += __shfl_xor(s, 1, 32);\n"
"            s += __shfl_xor(s, 2, 32);\n"
"            s += __shfl_xor(s, 4, 32);\n"
"            s += __shfl_xor(s, 8, 32);\n"
"            l_i[i] = l_i[i] * alpha[i] + s;\n"
"            m_i[i] = new_max;\n"
"            score[i] = ej;\n"
"        }\n"
"        for (int kb = 0; kb < FA_LLM_K_NB; kb++)\n"
"            for (int i = 0; i < 8; i++) O_acc[kb][i] *= alpha[i];\n"
"        for (int i = 0; i < 8; i++) {\n"
"            int m_row = half * 8 + i;\n"
"            int n_col = idx;\n"
"            smP_w[m_row * 16 + n_col] = (_Float16)score[i];\n"
"        }\n"
"        f16x8 ap;\n"
"        for (int i = 0; i < 8; i++) ap[i] = smP_w[idx * 16 + half * 8 + i];\n"
"        for (int kb = 0; kb < FA_LLM_K_NB; kb++) {\n"
"            f16x8 bv;\n"
"            for (int i = 0; i < 8; i++) {\n"
"                int d_col = kb * 16 + idx;\n"
"                int kv_k  = half * 8 + i;\n"
"                bv[i] = smV_cur[d_col * 16 + kv_k];\n"
"            }\n"
"            O_acc[kb] = __builtin_amdgcn_wmma_f32_16x16x16_f16_w32_gfx12(ap, bv, O_acc[kb]);\n"
"        }\n"
"        __syncthreads();\n"
"    }\n"
"    for (int kb = 0; kb < FA_LLM_K_NB; kb++) {\n"
"        for (int i = 0; i < 8; i++) {\n"
"            int m_row = half * 8 + i;\n"
"            int d = kb * 16 + idx;\n"
"            int row = q_base + m_row;\n"
"            if (row < M && d < head_dim) {\n"
"                float v = O_acc[kb][i] / (l_i[i] > 0.0f ? l_i[i] : 1.0f);\n"
"                out[(size_t)row * q_dim + h * head_dim + d] = v;\n"
"            }\n"
"        }\n"
"    }\n"
"}\n"
"#undef FA_LLM_BQ\n"
"#undef FA_LLM_BKV\n"
"#undef FA_LLM_HD_MAX\n"
"#undef FA_LLM_K_NB\n"
"\n"
"/* ---- head_dim=512 WMMA flash for Gemma4 full-attention (4 waves, head_dim split).\n"
" * head_dim 512 makes a single-wave O accumulator 256 VGPR (or 32 KB LDS), which\n"
" * collapses occupancy. Instead split the head_dim across 4 waves: each wave owns\n"
" * 128 output dims, so its O lives in registers (8 f32x8 = 64 VGPR). For QK each\n"
" * wave contracts only its 128 dims into a PARTIAL score; the 4 partials are summed\n"
" * via LDS to the full score, which all waves then softmax. Reads the F32 KV cache\n"
" * directly (K = RoPE'd key, V = un-RoPE'd normed key). LDS ~36.5 KB. BQ=16.\n"
" * Grid: (n_heads, ceil(M/16)). Block: 128. */\n"
"#define FW512_BQ 16\n"
"#define FW512_BKV 16\n"
"__global__ void flash_attn_wmma_hd512_causal(\n"
"    float *out, const float *Q, const float *key_cache, const float *value_cache,\n"
"    int M, int kv_len, int position_start, int n_heads, int n_kv_heads,\n"
"    int head_dim, int kv_dim, float scale) {\n"
"    int h  = blockIdx.x;\n"
"    int qb = blockIdx.y;\n"
"    int q0 = qb * FW512_BQ;\n"
"    int gqa = n_heads / n_kv_heads;\n"
"    int kv_h = h / gqa;\n"
"    int q_dim = n_heads * head_dim;\n"
"    int tid = threadIdx.x;\n"
"    int wid = tid >> 5;       /* 0..3, which 128-dim head slice this wave owns */\n"
"    int lid = tid & 31;\n"
"    int half = lid >> 4;\n"
"    int idx  = lid & 15;\n"
"    int dbase = wid * 128;    /* this wave's head_dim offset */\n"
"    extern __shared__ _Float16 smem512[];\n"
"    _Float16 *smK = smem512;                  /* [16*512] f16 (key*512 + d) */\n"
"    _Float16 *smV = smK + 16 * 512;           /* [16*512] f16 (d*16 + key)  */\n"
"    float    *smScore = (float*)(smV + 16 * 512); /* [4*256] partial scores  */\n"
"    _Float16 *smP = smK;                       /* [16*16] overlaps smK after QK */\n"
"    /* Q for this wave's 8 k-chunks (128 dims), scaled. */\n"
"    f16x8 q_reg[8];\n"
"    for (int kb = 0; kb < 8; kb++)\n"
"        for (int i = 0; i < 8; i++) {\n"
"            int d = dbase + kb * 16 + half * 8 + i;\n"
"            int row = q0 + idx;\n"
"            float v = (row < M && d < head_dim) ? Q[(size_t)row * q_dim + h * head_dim + d] : 0.0f;\n"
"            q_reg[kb][i] = (_Float16)(v * scale);\n"
"        }\n"
"    float8 O_acc[8];\n"
"    for (int kb = 0; kb < 8; kb++) for (int i = 0; i < 8; i++) O_acc[kb][i] = 0.0f;\n"
"    float m_i[8], l_i[8];\n"
"    for (int i = 0; i < 8; i++) { m_i[i] = -1e30f; l_i[i] = 0.0f; }\n"
"    int max_kv = position_start + q0 + FW512_BQ;\n"
"    if (max_kv > kv_len) max_kv = kv_len;\n"
"    int n_kv = (max_kv + FW512_BKV - 1) / FW512_BKV;\n"
"    for (int t = 0; t < n_kv; t++) {\n"
"        int kv0 = t * FW512_BKV;\n"
"        for (int e = tid; e < 16 * 512; e += 128) {\n"
"            int key = e >> 9; int d = e & 511;\n"
"            int kpos = kv0 + key;\n"
"            float kf = 0.0f, vf = 0.0f;\n"
"            if (kpos < max_kv) {\n"
"                size_t base = (size_t)kpos * kv_dim + kv_h * head_dim + d;\n"
"                kf = key_cache[base]; vf = value_cache[base];\n"
"            }\n"
"            smK[key * 512 + d] = (_Float16)kf;\n"
"            smV[d * 16 + key]  = (_Float16)vf;\n"
"        }\n"
"        __syncthreads();\n"
"        /* Partial QK over this wave's 128 dims. */\n"
"        float8 sp = {0,0,0,0,0,0,0,0};\n"
"        for (int kb = 0; kb < 8; kb++) {\n"
"            f16x8 bK;\n"
"            for (int i = 0; i < 8; i++) { int dpos = dbase + kb * 16 + half * 8 + i; bK[i] = smK[idx * 512 + dpos]; }\n"
"            sp = __builtin_amdgcn_wmma_f32_16x16x16_f16_w32_gfx12(q_reg[kb], bK, sp);\n"
"        }\n"
"        /* Reduce the 4 waves' partial scores to the full score via LDS. */\n"
"        for (int i = 0; i < 8; i++) smScore[wid * 256 + lid * 8 + i] = sp[i];\n"
"        __syncthreads();\n"
"        float8 score;\n"
"        for (int i = 0; i < 8; i++)\n"
"            score[i] = smScore[0 * 256 + lid * 8 + i] + smScore[1 * 256 + lid * 8 + i]\n"
"                     + smScore[2 * 256 + lid * 8 + i] + smScore[3 * 256 + lid * 8 + i];\n"
"        bool col_valid = (kv0 + idx) < max_kv;\n"
"        for (int i = 0; i < 8; i++) score[i] = col_valid ? score[i] : -1e30f;\n"
"        int k_global = kv0 + idx;\n"
"        for (int i = 0; i < 8; i++) { int qg = position_start + q0 + half * 8 + i; if (qg < k_global) score[i] = -1e30f; }\n"
"        float row_max[8];\n"
"        for (int i = 0; i < 8; i++) { float v = score[i];\n"
"            v = fmaxf(v, __shfl_xor(v,1,32)); v = fmaxf(v, __shfl_xor(v,2,32));\n"
"            v = fmaxf(v, __shfl_xor(v,4,32)); v = fmaxf(v, __shfl_xor(v,8,32)); row_max[i] = v; }\n"
"        float alpha[8];\n"
"        for (int i = 0; i < 8; i++) { float nm = fmaxf(m_i[i], row_max[i]);\n"
"            alpha[i] = (m_i[i] < -1e29f) ? 0.0f : __expf(m_i[i] - nm);\n"
"            float ej = __expf(score[i] - nm); float s = ej;\n"
"            s += __shfl_xor(s,1,32); s += __shfl_xor(s,2,32); s += __shfl_xor(s,4,32); s += __shfl_xor(s,8,32);\n"
"            l_i[i] = l_i[i] * alpha[i] + s; m_i[i] = nm; score[i] = ej; }\n"
"        for (int kb = 0; kb < 8; kb++) for (int i = 0; i < 8; i++) O_acc[kb][i] *= alpha[i];\n"
"        __syncthreads();   /* before overwriting smK with smP */\n"
"        for (int i = 0; i < 8; i++) smP[(half * 8 + i) * 16 + idx] = (_Float16)score[i];\n"
"        __syncthreads();\n"
"        f16x8 ap;\n"
"        for (int i = 0; i < 8; i++) ap[i] = smP[idx * 16 + half * 8 + i];\n"
"        for (int kb = 0; kb < 8; kb++) {\n"
"            f16x8 bv;\n"
"            for (int i = 0; i < 8; i++) { int d_col = dbase + kb * 16 + idx; int kv_k = half * 8 + i; bv[i] = smV[d_col * 16 + kv_k]; }\n"
"            O_acc[kb] = __builtin_amdgcn_wmma_f32_16x16x16_f16_w32_gfx12(ap, bv, O_acc[kb]);\n"
"        }\n"
"        __syncthreads();\n"
"    }\n"
"    for (int kb = 0; kb < 8; kb++)\n"
"        for (int i = 0; i < 8; i++) {\n"
"            int m_row = half * 8 + i; int d = dbase + kb * 16 + idx; int row = q0 + m_row;\n"
"            if (row < M && d < head_dim) {\n"
"                float v = O_acc[kb][i] / (l_i[i] > 0.0f ? l_i[i] : 1.0f);\n"
"                out[(size_t)row * q_dim + h * head_dim + d] = v;\n"
"            }\n"
"        }\n"
"}\n"
"#undef FW512_BQ\n"
"#undef FW512_BKV\n"
"\n"
"/* ===== Phase 4: WMMA F16 matvec for decode (M=1) ===== */\n"
"/* Computes dst[n_rows] = mat[n_rows, n_cols] * x[n_cols] using 16-row WMMA tiles.\n"
" * x is staged into LDS as F16 once. 4 waves per WG, each wave handles its own\n"
" * 16-row tile -> WG covers 64 rows. B operand is x replicated across all 16\n"
" * N columns; we read column 0 of the result.\n"
" * Grid: ceil(n_rows / 64). Block: 128 (4 waves). Shared mem: n_cols * 2 bytes. */\n"
"__global__ void matvec_f16_wmma_f32(float *dst, const half_raw *mat,\n"
"                                     const float *x, int n_rows, int n_cols) {\n"
"    int tid = threadIdx.x;\n"
"    int wave = tid >> 5;\n"
"    int lane = tid & 31;\n"
"    int half = lane >> 4;\n"
"    int idx  = lane & 15;\n"
"    int row_tile = blockIdx.x * 4 + wave;\n"
"    int row0 = row_tile * 16;\n"
"    extern __shared__ _Float16 sm_x_h[];\n"
"    /* All threads in WG cooperate to load x to LDS as F16. */\n"
"    int n4 = n_cols & ~3;\n"
"    for (int i = tid * 4; i < n4; i += blockDim.x * 4) {\n"
"        float4 f = *(const float4 *)(x + i);\n"
"        sm_x_h[i + 0] = (_Float16)f.x;\n"
"        sm_x_h[i + 1] = (_Float16)f.y;\n"
"        sm_x_h[i + 2] = (_Float16)f.z;\n"
"        sm_x_h[i + 3] = (_Float16)f.w;\n"
"    }\n"
"    for (int i = n4 + tid; i < n_cols; i += blockDim.x) {\n"
"        sm_x_h[i] = (_Float16)x[i];\n"
"    }\n"
"    __syncthreads();\n"
"    if (row0 >= n_rows) return;\n"
"    int row = row0 + idx;\n"
"    int row_in = (row < n_rows) ? row : 0;\n"
"    const _Float16 *row_h = (const _Float16 *)mat + (size_t)row_in * n_cols;\n"
"    int n_kt = n_cols / 16;\n"
"    float8 acc = {0,0,0,0,0,0,0,0};\n"
"    for (int kt = 0; kt < n_kt; kt++) {\n"
"        /* Vector load: 8 consecutive F16 from this lane's row at kt*16 + half*8. */\n"
"        f16x8 a = *(const f16x8 *)(row_h + kt * 16 + half * 8);\n"
"        f16x8 b = *(const f16x8 *)(sm_x_h + kt * 16 + half * 8);\n"
"        acc = __builtin_amdgcn_wmma_f32_16x16x16_f16_w32_gfx12(a, b, acc);\n"
"    }\n"
"    /* Tail: cols not multiple of 16. */\n"
"    int kt_tail = n_kt * 16;\n"
"    if (kt_tail < n_cols) {\n"
"        f16x8 a = {0,0,0,0,0,0,0,0};\n"
"        f16x8 b = {0,0,0,0,0,0,0,0};\n"
"        for (int i = 0; i < 8; i++) {\n"
"            int col = kt_tail + half * 8 + i;\n"
"            if (col < n_cols) {\n"
"                a[i] = row_h[col];\n"
"                b[i] = sm_x_h[col];\n"
"            }\n"
"        }\n"
"        acc = __builtin_amdgcn_wmma_f32_16x16x16_f16_w32_gfx12(a, b, acc);\n"
"    }\n"
"    /* acc[i] in lane (idx, half) holds C[M=half*8+i, N=idx]. Take any single N. */\n"
"    if (idx == 0) {\n"
"        for (int i = 0; i < 8; i++) {\n"
"            int row = row0 + half * 8 + i;\n"
"            if (row < n_rows) dst[row] = acc[i];\n"
"        }\n"
"    }\n"
"}\n"
"\n"
"/* ===== Phase 5: device-pointer position kernels for HIP graph capture ===== */\n"
"/* These mirror rope_neox_f32 / rope_mrope_f32 / kv_cache_store / attn_decode_f32\n"
" * but read position from a device int so a captured graph can be replayed for\n"
" * any (token_id, position) by writing those scalars to *_p before launch. */\n"
"\n"
"__global__ void rope_neox_f32_devp(float *vec, int n_heads, int head_dim,\n"
"                                    const int *pos_p,\n"
"                                    float freq_base, int n_rope_pairs,\n"
"                                    const float *freq_factors) {\n"
"    int h = blockIdx.x;\n"
"    if (h >= n_heads) return;\n"
"    int j = threadIdx.x;\n"
"    int half_dim = head_dim / 2;\n"
"    if (j >= half_dim) return;\n"
"    if (n_rope_pairs > 0 && j >= n_rope_pairs) return;\n"
"    int pair_off = (n_rope_pairs > 0 && n_rope_pairs < half_dim) ? n_rope_pairs : half_dim;\n"
"    int rope_dim = (n_rope_pairs > 0) ? 2 * n_rope_pairs : head_dim;\n"
"    int pos = *pos_p;\n"
"    float freq = 1.0f / powf(freq_base, (float)(2 * j) / (float)rope_dim);\n"
"    if (freq_factors) freq /= freq_factors[j];\n"
"    float theta = (float)pos * freq;\n"
"    float cos_t = cosf(theta);\n"
"    float sin_t = sinf(theta);\n"
"    float *v = vec + h * head_dim;\n"
"    float v0 = v[j];\n"
"    float v1 = v[j + pair_off];\n"
"    v[j]            = v0 * cos_t - v1 * sin_t;\n"
"    v[j + pair_off] = v0 * sin_t + v1 * cos_t;\n"
"}\n"
"\n"
"/* M-RoPE text-only: all three position axes share the same scalar. */\n"
"__global__ void rope_mrope_f32_devp(float *vec, int n_heads, int head_dim,\n"
"                                     const int *pos_p,\n"
"                                     float freq_base,\n"
"                                     int sect0, int sect1, int sect2, int sect3) {\n"
"    int h = blockIdx.x;\n"
"    if (h >= n_heads) return;\n"
"    int j = threadIdx.x;\n"
"    int half_dim = sect0 + sect1 + sect2 + sect3;\n"
"    if (j >= half_dim) return;\n"
"    int sect_sum = sect0 + sect1 + sect2 + sect3;\n"
"    int rope_dim = 2 * sect_sum;\n"
"    int pos_v = *pos_p;\n"
"    int pos;\n"
"    if (j < sect0) pos = pos_v;\n"
"    else if (j < sect0 + sect1) pos = pos_v;\n"
"    else if (j < sect0 + sect1 + sect2) pos = pos_v;\n"
"    else pos = 0;\n"
"    float freq = 1.0f / powf(freq_base, (float)(2 * j) / (float)rope_dim);\n"
"    float theta = (float)pos * freq;\n"
"    float cos_t = cosf(theta);\n"
"    float sin_t = sinf(theta);\n"
"    float *v = vec + h * head_dim;\n"
"    float v0 = v[j];\n"
"    float v1 = v[j + half_dim];\n"
"    v[j]            = v0 * cos_t - v1 * sin_t;\n"
"    v[j + half_dim] = v0 * sin_t + v1 * cos_t;\n"
"}\n"
"\n"
"__global__ void kv_cache_store_devp(float *key_cache, float *value_cache,\n"
"                                     const float *k, const float *v,\n"
"                                     const int *pos_p, int kv_dim, int cache_len) {\n"
"    int i = blockIdx.x * blockDim.x + threadIdx.x;\n"
"    if (i < kv_dim) {\n"
"        int position = *pos_p;\n"
"        int slot = (cache_len > 0) ? (position % cache_len) : position;\n"
"        key_cache[(size_t)slot * kv_dim + i] = k[i];\n"
"        value_cache[(size_t)slot * kv_dim + i] = v[i];\n"
"    }\n"
"}\n"
"\n"
"/* Same as attn_decode_f32 but seq_len comes from *pos_p + 1 at runtime. */\n"
"__global__ void attn_decode_f32_devp(float *out, const float *q,\n"
"                                      const float *key_cache, const float *value_cache,\n"
"                                      int n_heads, int n_kv_heads, int head_dim,\n"
"                                      int kv_dim, const int *pos_p, float scale) {\n"
"    extern __shared__ float att[];\n"
"    int h = blockIdx.x;\n"
"    if (h >= n_heads) return;\n"
"    int tid = threadIdx.x;\n"
"    int nthreads = blockDim.x;\n"
"    int gqa_ratio = n_heads / n_kv_heads;\n"
"    int kv_h = h / gqa_ratio;\n"
"    int seq_len = *pos_p + 1;\n"
"    const float *q_h = q + h * head_dim;\n"
"    for (int t = tid; t < seq_len; t += nthreads) {\n"
"        const float *k_t = key_cache + (size_t)t * kv_dim + kv_h * head_dim;\n"
"        float score = 0.0f;\n"
"        for (int d = 0; d < head_dim; d++) score += q_h[d] * k_t[d];\n"
"        att[t] = score * scale;\n"
"    }\n"
"    __syncthreads();\n"
"    float local_max = -1e30f;\n"
"    for (int t = tid; t < seq_len; t += nthreads) {\n"
"        if (att[t] > local_max) local_max = att[t];\n"
"    }\n"
"    for (int offset = 16; offset > 0; offset >>= 1) {\n"
"        float other = __shfl_down(local_max, offset);\n"
"        if (other > local_max) local_max = other;\n"
"    }\n"
"    __shared__ float warp_max[8];\n"
"    int warp_id = tid / 32;\n"
"    int lane = tid % 32;\n"
"    if (lane == 0) warp_max[warp_id] = local_max;\n"
"    __syncthreads();\n"
"    if (tid == 0) {\n"
"        float m = warp_max[0];\n"
"        int n_warps = (nthreads + 31) / 32;\n"
"        for (int w = 1; w < n_warps; w++) if (warp_max[w] > m) m = warp_max[w];\n"
"        warp_max[0] = m;\n"
"    }\n"
"    __syncthreads();\n"
"    float max_val = warp_max[0];\n"
"    float local_sum = 0.0f;\n"
"    for (int t = tid; t < seq_len; t += nthreads) {\n"
"        float e = expf(att[t] - max_val);\n"
"        att[t] = e;\n"
"        local_sum += e;\n"
"    }\n"
"    for (int offset = 16; offset > 0; offset >>= 1) {\n"
"        local_sum += __shfl_down(local_sum, offset);\n"
"    }\n"
"    __shared__ float warp_sum[8];\n"
"    if (lane == 0) warp_sum[warp_id] = local_sum;\n"
"    __syncthreads();\n"
"    if (tid == 0) {\n"
"        float s = 0.0f;\n"
"        int n_warps = (nthreads + 31) / 32;\n"
"        for (int w = 0; w < n_warps; w++) s += warp_sum[w];\n"
"        warp_sum[0] = s;\n"
"    }\n"
"    __syncthreads();\n"
"    float inv_sum = 1.0f / warp_sum[0];\n"
"    for (int t = tid; t < seq_len; t += nthreads) att[t] *= inv_sum;\n"
"    __syncthreads();\n"
"    float *out_h = out + h * head_dim;\n"
"    for (int d = tid; d < head_dim; d += nthreads) {\n"
"        float acc = 0.0f;\n"
"        for (int t = 0; t < seq_len; t++) {\n"
"            const float *v_t = value_cache + (size_t)t * kv_dim + kv_h * head_dim;\n"
"            acc += att[t] * v_t[d];\n"
"        }\n"
"        out_h[d] = acc;\n"
"    }\n"
"}\n"
"\n"
"/* ---- Gemma4 kernels ---- */\n"
"\n"
"/* GELU * up: gate[i] = gelu(gate[i]) * up[i] */\n"
"__global__ void gelu_mul_f32(float *gate, const float *up, int n) {\n"
"    int i = blockIdx.x * blockDim.x + threadIdx.x;\n"
"    if (i >= n) return;\n"
"    float g = gate[i];\n"
"    float u = up[i];\n"
"    /* gelu_pytorch_tanh (Gemma's hidden_activation), matching ggml's tanh-approx\n"
"     * GELU. Exact erf GELU differs by ~1e-3 and that per-FFN error accumulates\n"
"     * over 48 layers into a garbled output on the Q4_0 QAT model. */\n"
"    float gelu_g = g * 0.5f * (1.0f + tanhf(0.7978845608028654f * (g + 0.044715f * g * g * g)));\n"
"    gate[i] = gelu_g * u;\n"
"}\n"
"\n"
"/* Logit softcapping: x[i] = cap * tanh(x[i] / cap) */\n"
"__global__ void logit_softcap_f32(float *x, int n, float cap) {\n"
"    int i = blockIdx.x * blockDim.x + threadIdx.x;\n"
"    if (i >= n) return;\n"
"    x[i] = cap * tanhf(x[i] / cap);\n"
"}\n"
"\n"
"/* Scale: x[i] *= scale */\n"
"__global__ void scale_f32(float *x, float scale, int n) {\n"
"    int i = blockIdx.x * blockDim.x + threadIdx.x;\n"
"    if (i >= n) return;\n"
"    x[i] *= scale;\n"
"}\n"
"\n"
"\n"
"/* Batched weightless per-head RMS norm. grid=(n_heads, M), block 256, smem 256 floats.\n"
" * Handles head_dim > blockDim (e.g. 512) via a grid-stride loop, unlike the single\n"
" * tid<head_dim variant above. Used for Gemma4 V normalization (V is rms-normed per head). */\n"
"__global__ void raw_rmsnorm_heads_batch_f32(float *vec_batch, int n_heads, int head_dim,\n"
"                                            int M, int row_stride, float eps) {\n"
"    extern __shared__ float sdata[];\n"
"    int h = blockIdx.x;\n"
"    int row = blockIdx.y;\n"
"    if (h >= n_heads || row >= M) return;\n"
"    int tid = threadIdx.x;\n"
"    int NT = blockDim.x;\n"
"    float *v = vec_batch + (size_t)row * row_stride + h * head_dim;\n"
"    float sum = 0.0f;\n"
"    for (int d = tid; d < head_dim; d += NT) { float x = v[d]; sum += x * x; }\n"
"    sdata[tid] = sum; __syncthreads();\n"
"    for (int s = NT / 2; s > 0; s >>= 1) { if (tid < s) sdata[tid] += sdata[tid + s]; __syncthreads(); }\n"
"    float scale = rsqrtf(sdata[0] / (float)head_dim + eps);\n"
"    for (int d = tid; d < head_dim; d += NT) v[d] *= scale;\n"
"}\n"
"\n"
"\n"
"\n"
"/* Flash (online-softmax) prefill attention. One block per (head, query row).\n"
" * Bounded shared memory = (2*head_dim + 2*blockDim) floats regardless of seq_len,\n"
" * so it scales to arbitrarily long sequences (pp32k) without exceeding LDS.\n"
" *   window > 0 : sliding-window attention, keys restricted to [pos-window+1, pos].\n"
" *   window == 0: full causal attention, keys [0, pos].\n"
" *   cache_len  : circular cache size (slot = pos %% cache_len). For full-attn this\n"
" *                equals max_seq_len so the modulo is a no-op. */\n"
"__global__ void attn_prefill_flash_f32(float *out, const float *q,\n"
"    const float *key_cache, const float *value_cache,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim,\n"
"    int M, int position_start, float scale, int window, int cache_len) {\n"
"    extern __shared__ float smem[];\n"
"    int h = blockIdx.x;\n"
"    int m = blockIdx.y;\n"
"    if (h >= n_heads || m >= M) return;\n"
"    int kv_h = h / (n_heads / n_kv_heads);\n"
"    int pos = position_start + m;\n"
"    int lo = (window > 0 && (pos - window + 1) > 0) ? (pos - window + 1) : 0;\n"
"    int hi = pos;\n"
"    int tid = threadIdx.x;\n"
"    int NT  = blockDim.x;\n"
"    float *q_sh   = smem;                  /* head_dim */\n"
"    float *acc_sh = q_sh + head_dim;       /* head_dim */\n"
"    float *p_sh   = acc_sh + head_dim;     /* NT       */\n"
"    float *red    = p_sh + NT;             /* NT       */\n"
"    const float *qh = q + (size_t)m * n_heads * head_dim + h * head_dim;\n"
"    for (int d = tid; d < head_dim; d += NT) { q_sh[d] = qh[d] * scale; acc_sh[d] = 0.0f; }\n"
"    __syncthreads();\n"
"    float m_i = -1e30f, l_i = 0.0f;\n"
"    for (int ts = lo; ts <= hi; ts += NT) {\n"
"        int kpos = ts + tid;\n"
"        int tile_n = hi - ts + 1; if (tile_n > NT) tile_n = NT;\n"
"        float score = -1e30f;\n"
"        if (kpos <= hi) {\n"
"            int slot = (cache_len > 0) ? (kpos % cache_len) : kpos;\n"
"            const float *kp = key_cache + (size_t)slot * kv_dim + kv_h * head_dim;\n"
"            float s = 0.0f;\n"
"            for (int d = 0; d < head_dim; d++) s += q_sh[d] * kp[d];\n"
"            score = s;\n"
"        }\n"
"        red[tid] = score; __syncthreads();\n"
"        for (int s2 = NT / 2; s2 > 0; s2 >>= 1) { if (tid < s2) red[tid] = fmaxf(red[tid], red[tid + s2]); __syncthreads(); }\n"
"        float tile_max = red[0];\n"
"        float new_m = fmaxf(m_i, tile_max);\n"
"        float corr  = (m_i < -1e29f) ? 0.0f : __expf(m_i - new_m);\n"
"        float pv = (kpos <= hi) ? __expf(score - new_m) : 0.0f;\n"
"        __syncthreads();\n"
"        p_sh[tid] = pv; red[tid] = pv; __syncthreads();\n"
"        for (int s2 = NT / 2; s2 > 0; s2 >>= 1) { if (tid < s2) red[tid] += red[tid + s2]; __syncthreads(); }\n"
"        float tile_sum = red[0];\n"
"        l_i = l_i * corr + tile_sum;\n"
"        for (int d = tid; d < head_dim; d += NT) {\n"
"            float a = acc_sh[d] * corr;\n"
"            for (int t = 0; t < tile_n; t++) {\n"
"                int slot2 = (cache_len > 0) ? ((ts + t) % cache_len) : (ts + t);\n"
"                a += p_sh[t] * value_cache[(size_t)slot2 * kv_dim + kv_h * head_dim + d];\n"
"            }\n"
"            acc_sh[d] = a;\n"
"        }\n"
"        m_i = new_m;\n"
"        __syncthreads();\n"
"    }\n"
"    float inv = (l_i > 0.0f) ? (1.0f / l_i) : 0.0f;\n"
"    float *out_h = out + (size_t)m * n_heads * head_dim + h * head_dim;\n"
"    for (int d = tid; d < head_dim; d += NT) out_h[d] = acc_sh[d] * inv;\n"
"}\n"
"\n"
"/* Flash (online-softmax) decode attention (single query at *pos_p). Device-pointer\n"
" * position so it is HIP-graph-capturable. Bounded shared memory. window/cache_len\n"
" * semantics identical to attn_prefill_flash_f32. */\n"
"__global__ void attn_decode_flash_f32_devp(float *out, const float *q,\n"
"    const float *key_cache, const float *value_cache,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim,\n"
"    const int *pos_p, float scale, int window, int cache_len) {\n"
"    extern __shared__ float smem[];\n"
"    int h = blockIdx.x;\n"
"    if (h >= n_heads) return;\n"
"    int kv_h = h / (n_heads / n_kv_heads);\n"
"    int pos = *pos_p;\n"
"    int lo = (window > 0 && (pos - window + 1) > 0) ? (pos - window + 1) : 0;\n"
"    int hi = pos;\n"
"    int tid = threadIdx.x;\n"
"    int NT  = blockDim.x;\n"
"    float *q_sh   = smem;\n"
"    float *acc_sh = q_sh + head_dim;\n"
"    float *p_sh   = acc_sh + head_dim;\n"
"    float *red    = p_sh + NT;\n"
"    const float *qh = q + h * head_dim;\n"
"    for (int d = tid; d < head_dim; d += NT) { q_sh[d] = qh[d] * scale; acc_sh[d] = 0.0f; }\n"
"    __syncthreads();\n"
"    float m_i = -1e30f, l_i = 0.0f;\n"
"    for (int ts = lo; ts <= hi; ts += NT) {\n"
"        int kpos = ts + tid;\n"
"        int tile_n = hi - ts + 1; if (tile_n > NT) tile_n = NT;\n"
"        float score = -1e30f;\n"
"        if (kpos <= hi) {\n"
"            int slot = (cache_len > 0) ? (kpos % cache_len) : kpos;\n"
"            const float *kp = key_cache + (size_t)slot * kv_dim + kv_h * head_dim;\n"
"            float s = 0.0f;\n"
"            for (int d = 0; d < head_dim; d++) s += q_sh[d] * kp[d];\n"
"            score = s;\n"
"        }\n"
"        red[tid] = score; __syncthreads();\n"
"        for (int s2 = NT / 2; s2 > 0; s2 >>= 1) { if (tid < s2) red[tid] = fmaxf(red[tid], red[tid + s2]); __syncthreads(); }\n"
"        float tile_max = red[0];\n"
"        float new_m = fmaxf(m_i, tile_max);\n"
"        float corr  = (m_i < -1e29f) ? 0.0f : __expf(m_i - new_m);\n"
"        float pv = (kpos <= hi) ? __expf(score - new_m) : 0.0f;\n"
"        __syncthreads();\n"
"        p_sh[tid] = pv; red[tid] = pv; __syncthreads();\n"
"        for (int s2 = NT / 2; s2 > 0; s2 >>= 1) { if (tid < s2) red[tid] += red[tid + s2]; __syncthreads(); }\n"
"        float tile_sum = red[0];\n"
"        l_i = l_i * corr + tile_sum;\n"
"        for (int d = tid; d < head_dim; d += NT) {\n"
"            float a = acc_sh[d] * corr;\n"
"            for (int t = 0; t < tile_n; t++) {\n"
"                int slot2 = (cache_len > 0) ? ((ts + t) % cache_len) : (ts + t);\n"
"                a += p_sh[t] * value_cache[(size_t)slot2 * kv_dim + kv_h * head_dim + d];\n"
"            }\n"
"            acc_sh[d] = a;\n"
"        }\n"
"        m_i = new_m;\n"
"        __syncthreads();\n"
"    }\n"
"    float inv = (l_i > 0.0f) ? (1.0f / l_i) : 0.0f;\n"
"    float *out_h = out + h * head_dim;\n"
"    for (int d = tid; d < head_dim; d += NT) out_h[d] = acc_sh[d] * inv;\n"
"}\n"
"\n"
"__global__ void kv_cache_store_f16_devp(half_raw *kc, half_raw *vc,\n"
"    const float *k, const float *v, int kv_dim, const int *pos_p) {\n"
"    int i=blockIdx.x*blockDim.x+threadIdx.x; if(i>=kv_dim)return; size_t o=(size_t)(*pos_p)*kv_dim+i;\n"
"    kc[o]=f32_to_f16_bits(k[i]); vc[o]=f32_to_f16_bits(v[i]);\n"
"}\n"
"__global__ void kv_cache_store_f16_batch(half_raw *kc, half_raw *vc,\n"
"    const float *k, const float *v, int kv_dim, int position_start, int M) {\n"
"    int i=blockIdx.x*blockDim.x+threadIdx.x, total=M*kv_dim;\n"
"    if(i>=total)return; int m=i/kv_dim, d=i-m*kv_dim;\n"
"    size_t o=(size_t)(position_start+m)*kv_dim+d;\n"
"    kc[o]=f32_to_f16_bits(k[(size_t)m*kv_dim+d]);\n"
"    vc[o]=f32_to_f16_bits(v[(size_t)m*kv_dim+d]);\n"
"}\n"
"__global__ void kv_cache_store_i8_devp_v2(signed char *kc, signed char *vc,\n"
"    float *ks, float *vs, const float *k, const float *v, int n_kv_heads, int head_dim, const int *pos_p, int fp8) {\n"
"    int tid=threadIdx.x, pos=*pos_p, h=blockIdx.x; if(h>=n_kv_heads)return; int groups=(head_dim+31)/32;\n"
"    int kv_dim=n_kv_heads*head_dim, base=h*head_dim, group=tid>>5, lane=tid&31; float ak=(tid<head_dim)?fabsf(k[base+tid]):0.0f,av=(tid<head_dim)?fabsf(v[base+tid]):0.0f;\n"
"    for(int s=16;s;s>>=1){ak=fmaxf(ak,__shfl_down(ak,s,32));av=fmaxf(av,__shfl_down(av,s,32));}\n"
"    /* The launch is fixed at 256 threads, but head_dim may expose fewer than\n"
"     * eight 32-channel groups. Inactive warps must not spill scales into the\n"
"     * next KV head's row. */\n"
"    if(lane==0 && group<groups){ks[((size_t)pos*n_kv_heads+h)*groups+group]=fmaxf(ak/(fp8?1.0f:127.0f),1.0e-8f);vs[((size_t)pos*n_kv_heads+h)*groups+group]=fmaxf(av/(fp8?1.0f:127.0f),1.0e-8f);}\n"
"    __syncthreads(); for(int d=tid;d<head_dim;d+=blockDim.x){float sk=ks[((size_t)pos*n_kv_heads+h)*groups+d/32],sv=vs[((size_t)pos*n_kv_heads+h)*groups+d/32];size_t o=(size_t)pos*kv_dim+base+d;kc[o]=qkv_float_to_byte(k[base+d],sk,fp8);vc[o]=qkv_float_to_byte(v[base+d],sv,fp8);}\n"
"}\n"
"__global__ void kv_cache_store_i8_batch(signed char *kc, signed char *vc,\n"
"    float *ks, float *vs, const float *k, const float *v, int n_kv_heads, int head_dim, int position_start, int M, int fp8) {\n"
"    int bh=blockIdx.x, m=bh/n_kv_heads,h=bh%n_kv_heads,tid=threadIdx.x; if(m>=M)return; int groups=(head_dim+31)/32;\n"
"    int kv_dim=n_kv_heads*head_dim,base=h*head_dim,group=tid>>5,lane=tid&31; float ak=(tid<head_dim)?fabsf(k[(size_t)m*kv_dim+base+tid]):0.0f,av=(tid<head_dim)?fabsf(v[(size_t)m*kv_dim+base+tid]):0.0f;\n"
"    for(int s=16;s;s>>=1){ak=fmaxf(ak,__shfl_down(ak,s,32));av=fmaxf(av,__shfl_down(av,s,32));}\n"
"    int pos=position_start+m; if(lane==0 && group<groups){ks[((size_t)pos*n_kv_heads+h)*groups+group]=fmaxf(ak/(fp8?1.0f:127.0f),1.0e-8f);vs[((size_t)pos*n_kv_heads+h)*groups+group]=fmaxf(av/(fp8?1.0f:127.0f),1.0e-8f);} __syncthreads();\n"
"    for(int d=tid;d<head_dim;d+=blockDim.x){float sk=ks[((size_t)pos*n_kv_heads+h)*groups+d/32],sv=vs[((size_t)pos*n_kv_heads+h)*groups+d/32];size_t o=(size_t)pos*kv_dim+base+d;kc[o]=qkv_float_to_byte(k[(size_t)m*kv_dim+base+d],sk,fp8);vc[o]=qkv_float_to_byte(v[(size_t)m*kv_dim+base+d],sv,fp8);}\n"
"}\n"
"__device__ __forceinline__ signed char q4_quant(float x,float s) {\n"
"    /* Match ggml quantize_row_q4_0_ref: d is signed (max/-8), and the\n"
"     * integer conversion is truncation after adding the zero-point. */\n"
"    int q=(int)(x/s+8.5f); if(q<0)q=0; if(q>15)q=15; return (signed char)(q-8);\n"
"}\n"
"/* Q8/Q4 cache quantization follows ggml's block scale contracts. */\n"
"__global__ void kv_cache_store_q8q4_batch(signed char *kc, unsigned char *vc,\n"
"    float *ks, float *vs, const float *k, const float *v, int n_kv_heads, int head_dim, int position_start, int M) {\n"
"    int bh=blockIdx.x,m=bh/n_kv_heads,h=bh%n_kv_heads,tid=threadIdx.x; if(m>=M)return; int groups=(head_dim+31)/32;\n"
"    int kv_dim=n_kv_heads*head_dim,base=h*head_dim,group=tid>>5,lane=tid&31; float ak=(tid<head_dim)?fabsf(k[(size_t)m*kv_dim+base+tid]):0.0f,av=(tid<head_dim)?v[(size_t)m*kv_dim+base+tid]:0.0f; __shared__ float sk_raw_sh[32],sv_raw_sh[32];\n"
"    for(int s=16;s;s>>=1){ak=fmaxf(ak,__shfl_down(ak,s,32));}\n"
"    float av_max=av; for(int s=16;s;s>>=1){float z=__shfl_down(av_max,s,32);if(fabsf(z)>fabsf(av_max))av_max=z;}\n"
"    int pos=position_start+m; if(lane==0 && group<groups){float sk=fmaxf(ak/127.0f,1.0e-8f),sv=av_max/(-8.0f);if(fabsf(sv)<1.0e-8f)sv=1.0e-8f;sk_raw_sh[group]=sk;sv_raw_sh[group]=sv;ks[((size_t)pos*n_kv_heads+h)*groups+group]=round_f16_contract(sk);vs[((size_t)pos*n_kv_heads+h)*groups+group]=round_f16_contract(sv);} __syncthreads();\n"
"    /* ggml quantizes from the original FP32 block scale and only then\n"
"     * stores the FP16 scale. Keep both values here; using the rounded\n"
"     * scale for the integer decision changes cache codes. */\n"
"    for(int d=tid;d<head_dim;d+=blockDim.x){float sk=sk_raw_sh[d>>5];int q=(int)roundf(k[(size_t)m*kv_dim+base+d]/sk);q=q<-127?-127:q>127?127:q;size_t ko=(size_t)pos*kv_dim+base+d;kc[ko]=(signed char)q;}\n"
"    for(int bi=tid;bi<head_dim/2;bi+=blockDim.x){int g=bi/16,j=bi&15,lo=g*32+j,hi=lo+16;float sv=sv_raw_sh[g];int a=(int)(v[(size_t)m*kv_dim+base+lo]/sv+8.5f);if(a<0)a=0;if(a>15)a=15;int b=8;if(hi<head_dim){b=(int)(v[(size_t)m*kv_dim+base+hi]/sv+8.5f);if(b<0)b=0;if(b>15)b=15;}size_t vo=(size_t)pos*(n_kv_heads*(head_dim/2))+h*(head_dim/2)+bi;vc[vo]=(unsigned char)(a|(b<<4));}\n"
"}\n"
/* Both Q8_0 caches use the original FP32 scale for codes, FP16 for storage. */
"/* Match the HIP non-fast-math reciprocal refinement before integer rounding. */\n"
"__device__ __forceinline__ float q8_recip_contract(float b) {\n"
"    float r,e,nb=-b;\n"
"    asm volatile(\"v_rcp_f32 %0, %1\":\"=v\"(r):\"v\"(b));\n"
"    asm volatile(\"v_fma_f32 %0, %1, %2, 1.0\":\"=v\"(e):\"v\"(nb),\"v\"(r));\n"
"    asm volatile(\"v_fma_f32 %0, %1, %2, %3\":\"=v\"(r):\"v\"(e),\"v\"(r),\"v\"(r));\n"
"    asm volatile(\"v_fma_f32 %0, %1, %2, 1.0\":\"=v\"(e):\"v\"(nb),\"v\"(r));\n"
"    asm volatile(\"v_fma_f32 %0, %1, %2, %3\":\"=v\"(r):\"v\"(e),\"v\"(r),\"v\"(r));\n"
"    return r;\n"
"}\n"
"__device__ __forceinline__ float q8_div_contract(float a, float b) {\n"
"    float r=q8_recip_contract(b),q,e,nb=-b;\n"
"    asm volatile(\"v_mul_f32 %0, %1, %2\":\"=v\"(q):\"v\"(a),\"v\"(r));\n"
"    asm volatile(\"v_fma_f32 %0, %1, %2, %3\":\"=v\"(e):\"v\"(nb),\"v\"(q),\"v\"(a));\n"
"    asm volatile(\"v_fma_f32 %0, %1, %2, %3\":\"=v\"(q):\"v\"(e),\"v\"(r),\"v\"(q));\n"
"    return q;\n"
"}\n"
"__global__ void kv_cache_store_q8q8_batch(signed char *kc, signed char *vc,\n"
"    float *ks, float *vs, const float *k, const float *v, int n_kv_heads,\n"
"    int head_dim, int position_start, int M) {\n"
"    int m=blockIdx.x/n_kv_heads,h=blockIdx.x%n_kv_heads,tid=threadIdx.x;\n"
"    int lane=tid&31,group=tid>>5,groups=head_dim/32,kv_dim=n_kv_heads*head_dim;\n"
"    if(m>=M)return; size_t input=(size_t)m*kv_dim+h*head_dim+tid;\n"
"    float xk=tid<head_dim?k[input]:0.0f,xv=tid<head_dim?v[input]:0.0f;\n"
"    float ak=fabsf(xk),av=fabsf(xv);\n"
"    for(int z=16;z;z>>=1){ak=fmaxf(ak,__shfl_xor(ak,z,32));av=fmaxf(av,__shfl_xor(av,z,32));}\n"
"    float dk=q8_div_contract(ak,127.0f),dv=q8_div_contract(av,127.0f);\n"
"    float ik=dk?q8_recip_contract(dk):0.0f,iv=dv?q8_recip_contract(dv):0.0f;\n"
"    if(tid<head_dim){size_t o=(size_t)(position_start+m)*kv_dim+h*head_dim+tid;\n"
"        float qk,qv;asm volatile(\"v_mul_f32 %0, %1, %2\":\"=v\"(qk):\"v\"(xk),\"v\"(ik));asm volatile(\"v_mul_f32 %0, %1, %2\":\"=v\"(qv):\"v\"(xv),\"v\"(iv));kc[o]=(signed char)roundf(qk);vc[o]=(signed char)roundf(qv);\n"
"        if(lane==0){size_t sg=((size_t)(position_start+m)*n_kv_heads+h)*groups+group;\n"
"            ks[sg]=round_f16_contract(dk);vs[sg]=round_f16_contract(dv);}\n"
"    }\n"
"}\n"
"__global__ void kv_cache_store_q8q8_devp(signed char *kc, signed char *vc,\n"
"    float *ks, float *vs, const float *k, const float *v, int n_kv_heads,\n"
"    int head_dim, const int *position) {\n"
"    int position_start=*position, M=1; int m=blockIdx.x/n_kv_heads,h=blockIdx.x%n_kv_heads,tid=threadIdx.x;\n"
"    int lane=tid&31,group=tid>>5,groups=head_dim/32,kv_dim=n_kv_heads*head_dim;\n"
"    if(m>=M)return; size_t input=(size_t)m*kv_dim+h*head_dim+tid;\n"
"    float xk=tid<head_dim?k[input]:0.0f,xv=tid<head_dim?v[input]:0.0f;\n"
"    float ak=fabsf(xk),av=fabsf(xv);\n"
"    for(int z=16;z;z>>=1){ak=fmaxf(ak,__shfl_xor(ak,z,32));av=fmaxf(av,__shfl_xor(av,z,32));}\n"
"    float dk=q8_div_contract(ak,127.0f),dv=q8_div_contract(av,127.0f);\n"
"    float ik=dk?q8_recip_contract(dk):0.0f,iv=dv?q8_recip_contract(dv):0.0f;\n"
"    if(tid<head_dim){size_t o=(size_t)(position_start+m)*kv_dim+h*head_dim+tid;\n"
"        float qk,qv;asm volatile(\"v_mul_f32 %0, %1, %2\":\"=v\"(qk):\"v\"(xk),\"v\"(ik));asm volatile(\"v_mul_f32 %0, %1, %2\":\"=v\"(qv):\"v\"(xv),\"v\"(iv));kc[o]=(signed char)roundf(qk);vc[o]=(signed char)roundf(qv);\n"
"        if(lane==0){size_t sg=((size_t)(position_start+m)*n_kv_heads+h)*groups+group;\n"
"            ks[sg]=round_f16_contract(dk);vs[sg]=round_f16_contract(dv);}\n"
"    }\n"
"}\n"
/* The max reduction and probability-sum reduction reuse red[]. Every wave
 * must finish reading the maximum before any wave publishes its sum input. */
"__global__ void attn_decode_flash_f16_devp(float *out, const float *q,\n"
"    const half_raw *key_cache, const half_raw *value_cache,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim,\n"
"    const int *pos_p, float scale) {\n"
"    extern __shared__ float smem[]; int h=blockIdx.x; if(h>=n_heads)return;\n"
"    int kv_h=h/(n_heads/n_kv_heads), pos=*pos_p, tid=threadIdx.x, NT=blockDim.x;\n"
"    float *q_sh=smem,*acc=q_sh+head_dim,*prob=acc+head_dim,*red=prob+NT;\n"
"    const float *qh=q+h*head_dim; for(int d=tid;d<head_dim;d+=NT){\n"
"      /* llama.cpp's F16 vector fallback loads Q into half2 registers and\n"
"       * applies the (power-of-two for head_dim=256) scale there. Round Q\n"
"       * to F16 before the dot so Q8/Q4-cache fallback uses the same\n"
"       * operand contract instead of retaining an F32 query. */\n"
"      q_sh[d]=half_to_float(f32_to_f16_bits(qh[d]*scale)); acc[d]=0.0f; }\n"
"    __syncthreads(); float mi=-1e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=NT){ int kp=ts+tid, tn=pos-ts+1; if(tn>NT)tn=NT; float sc=-1e30f;\n"
"      if(kp<=pos){const half_raw *kr=key_cache+(size_t)kp*kv_dim+kv_h*head_dim;sc=0.0f;\n"
"        for(int d=0;d<head_dim;d++)sc+=q_sh[d]*half_to_float(kr[d]);}\n"
"      float rv=sc;int lane=tid&31,warp=tid>>5;for(int z=16;z;z>>=1)rv=fmaxf(rv,__shfl_down(rv,z,32));\n"
"      if(lane==0)red[warp]=rv;__syncthreads();if(warp==0){rv=tid<8?red[tid]:-1e30f;\n"
"        for(int z=16;z;z>>=1)rv=fmaxf(rv,__shfl_down(rv,z,32));if(tid==0)red[0]=rv;}__syncthreads();\n"
"      float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<=pos?__expf(sc-nm):0.0f;\n"
"      /* QWEN4_ATTN_MAX_READERS */ __syncthreads();prob[tid]=pv;rv=pv;for(int z=16;z;z>>=1)rv+=__shfl_down(rv,z,32);\n"
"      if(lane==0)red[warp]=rv;__syncthreads();if(warp==0){rv=tid<8?red[tid]:0.0f;\n"
"        for(int z=16;z;z>>=1)rv+=__shfl_down(rv,z,32);if(tid==0)red[0]=rv;}__syncthreads();\n"
"      li=li*corr+red[0];for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++)\n"
"        a+=prob[t]*half_to_float(value_cache[(size_t)(ts+t)*kv_dim+kv_h*head_dim+d]);acc[d]=a;}\n"
"      mi=nm;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=NT)out[h*head_dim+d]=acc[d]*inv;\n"
"}\n"
/* Exact per-column replication: each block computes the same score/probability
 * reductions, but owns a disjoint range of output columns. */
"__global__ void attn_decode_flash_f16_sharded(float *out, const float *q,\n"
"    const half_raw *key_cache, const half_raw *value_cache,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim,\n"
"    const int *pos_p, float scale) {\n"
"    extern __shared__ float smem[]; int h=blockIdx.x; if(h>=n_heads)return;\n"
"    int kv_h=h/(n_heads/n_kv_heads), pos=*pos_p, tid=threadIdx.x, NT=blockDim.x;\n"
"    int first=head_dim*blockIdx.y/gridDim.y,last=head_dim*(blockIdx.y+1)/gridDim.y;\n"
"    float *q_sh=smem,*acc=q_sh+head_dim,*prob=acc+head_dim,*red=prob+NT;\n"
"    const float *qh=q+h*head_dim; for(int d=tid;d<head_dim;d+=NT){q_sh[d]=qh[d]*scale;acc[d]=0.0f;}\n"
"    __syncthreads(); float mi=-1e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=NT){ int kp=ts+tid, tn=pos-ts+1; if(tn>NT)tn=NT; float sc=-1e30f;\n"
"      if(kp<=pos){const half_raw *kr=key_cache+(size_t)kp*kv_dim+kv_h*head_dim;sc=0.0f;\n"
"        for(int d=0;d<head_dim;d++)sc+=q_sh[d]*half_to_float(kr[d]);}\n"
"      float rv=sc;int lane=tid&31,warp=tid>>5;for(int z=16;z;z>>=1)rv=fmaxf(rv,__shfl_down(rv,z,32));\n"
"      if(lane==0)red[warp]=rv;__syncthreads();if(warp==0){rv=tid<8?red[tid]:-1e30f;\n"
"        for(int z=16;z;z>>=1)rv=fmaxf(rv,__shfl_down(rv,z,32));if(tid==0)red[0]=rv;}__syncthreads();\n"
"      float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<=pos?__expf(sc-nm):0.0f;\n"
"      /* QWEN4_ATTN_MAX_READERS */ __syncthreads();prob[tid]=pv;rv=pv;for(int z=16;z;z>>=1)rv+=__shfl_down(rv,z,32);\n"
"      if(lane==0)red[warp]=rv;__syncthreads();if(warp==0){rv=tid<8?red[tid]:0.0f;\n"
"        for(int z=16;z;z>>=1)rv+=__shfl_down(rv,z,32);if(tid==0)red[0]=rv;}__syncthreads();\n"
"      li=li*corr+red[0];for(int d=first+tid;d<last;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++)\n"
"        a+=prob[t]*half_to_float(value_cache[(size_t)(ts+t)*kv_dim+kv_h*head_dim+d]);acc[d]=a;}\n"
"      mi=nm;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=first+tid;d<last;d+=NT)out[h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"__global__ void attn_decode_gqa8_f16(float *out, const float *q,\n"
"    const half_raw *key_cache, const half_raw *value_cache,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim, const int *pos_p, float scale) {\n"
"    extern __shared__ float smem[]; int h=blockIdx.x;if(h>=n_heads)return;\n"
"    int kv_h=h/(n_heads/n_kv_heads),pos=*pos_p,tid=threadIdx.x,key=tid>>3,lane=tid&7;\n"
"    float *q_sh=smem,*acc=q_sh+head_dim,*prob=acc+head_dim,*red=prob+256;\n"
"    for(int d=tid;d<head_dim;d+=blockDim.x){q_sh[d]=q[h*head_dim+d]*scale;acc[d]=0.0f;}\n"
"    __syncthreads();float mi=-1e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=32){int tn=pos-ts+1;if(tn>32)tn=32;float sc=-1e30f;\n"
"      if(key<tn){const half_raw *kr=key_cache+(size_t)(ts+key)*kv_dim+kv_h*head_dim;\n"
"        for(int d=lane;d<head_dim;d+=8)sc+=q_sh[d]*half_to_float(kr[d]);\n"
"        sc+=__shfl_down(sc,4,8);sc+=__shfl_down(sc,2,8);sc+=__shfl_down(sc,1,8);}\n"
"      if(tid<32)red[tid]=-1e30f;if(lane==0&&key<tn)red[key]=sc;__syncthreads();\n"
"      for(int z=16;z;z>>=1){if(tid<z)red[tid]=fmaxf(red[tid],red[tid+z]);__syncthreads();}\n"
"      float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm);\n"
"      if(tid<32)prob[tid]=tid<tn?__expf(red[tid]-nm):0.0f;__syncthreads();\n"
"      if(tid<32)red[tid]=prob[tid];__syncthreads();\n"
"      for(int z=16;z;z>>=1){if(tid<z)red[tid]+=red[tid+z];__syncthreads();}\n"
"      li=li*corr+red[0];for(int d=tid;d<head_dim;d+=blockDim.x){float a=acc[d]*corr;\n"
"        for(int t=0;t<tn;t++)a+=prob[t]*half_to_float(value_cache[(size_t)(ts+t)*kv_dim+kv_h*head_dim+d]);acc[d]=a;}\n"
"      mi=nm;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=blockDim.x)out[h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"__global__ void attn_decode_flash_i8(float *out, const float *q,\n"
"    const signed char *key_cache, const signed char *value_cache, const float *key_scale, const float *value_scale,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim, const int *pos_p, float scale, int fp8) {\n"
"    extern __shared__ float smem[]; int h=blockIdx.x;if(h>=n_heads)return;int kv_h=h/(n_heads/n_kv_heads),pos=*pos_p,tid=threadIdx.x,NT=blockDim.x,groups=(head_dim+31)/32;\n"
"    float *q_sh=smem,*acc=q_sh+head_dim,*prob=acc+head_dim,*red=prob+NT;const float *qh=q+h*head_dim;\n"
"    for(int d=tid;d<head_dim;d+=NT){q_sh[d]=qh[d]*scale;acc[d]=0.0f;}__syncthreads();float mi=-1e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=NT){int kp=ts+tid,tn=pos-ts+1;if(tn>NT)tn=NT;float sc=-1e30f;\n"
"      if(kp<=pos){const signed char *kr=key_cache+(size_t)kp*kv_dim+kv_h*head_dim;sc=0.0f;for(int d=0;d<head_dim;d++)sc+=q_sh[d]*qkv_byte_to_float(kr[d],key_scale[((size_t)kp*n_kv_heads+kv_h)*groups+d/32],fp8);}\n"
"      float rv=sc;int lane=tid&31,warp=tid>>5;for(int z=16;z;z>>=1)rv=fmaxf(rv,__shfl_down(rv,z,32));if(lane==0)red[warp]=rv;__syncthreads();\n"
"      if(warp==0){rv=tid<8?red[tid]:-1e30f;for(int z=16;z;z>>=1)rv=fmaxf(rv,__shfl_down(rv,z,32));if(tid==0)red[0]=rv;}__syncthreads();\n"
"      float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<=pos?__expf(sc-nm):0.0f;/* QWEN4_ATTN_MAX_READERS */ __syncthreads();prob[tid]=pv;rv=pv;for(int z=16;z;z>>=1)rv+=__shfl_down(rv,z,32);\n"
"      if(lane==0)red[warp]=rv;__syncthreads();if(warp==0){rv=tid<8?red[tid]:0.0f;for(int z=16;z;z>>=1)rv+=__shfl_down(rv,z,32);if(tid==0)red[0]=rv;}__syncthreads();\n"
"      li=li*corr;for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++)a+=prob[t]*qkv_byte_to_float(value_cache[(size_t)(ts+t)*kv_dim+kv_h*head_dim+d],value_scale[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32],fp8);acc[d]=a;}li+=red[0];mi=nm;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=NT)out[h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"__device__ __forceinline__ float q4_cache_to_float(const unsigned char *vc, size_t i, float s, int d) {\n"
"    unsigned char p=vc[i]; int q=(d&1)?(p>>4):(p&15); return (float)(q-8)*s;\n"
"}\n"
"__global__ void attn_decode_flash_q8q4(float *out, const float *q, const signed char *kc, const unsigned char *vc, const float *ks, const float *vs, int n_heads, int n_kv_heads, int head_dim, int kv_dim, int value_stride, const int *pos_p, float scale) {\n"
"    extern __shared__ float smem[]; int h=blockIdx.x;if(h>=n_heads)return;int kv_h=h/(n_heads/n_kv_heads),pos=*pos_p,tid=threadIdx.x,NT=blockDim.x,groups=(head_dim+31)/32;float *qv=smem,*acc=qv+head_dim,*pr=acc+head_dim,*red=pr+NT;\n"
"    for(int d=tid;d<head_dim;d+=NT){qv[d]=q[h*head_dim+d]*scale;acc[d]=0.0f;}__syncthreads();float mi=-1e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=NT){int kp=ts+tid,tn=pos-ts+1;if(tn>NT)tn=NT;float sc=-1e30f;if(kp<=pos){const signed char *kr=kc+(size_t)kp*kv_dim+kv_h*head_dim;for(int d=0;d<head_dim;d++)sc+=qv[d]*(float)kr[d]*ks[((size_t)kp*n_kv_heads+kv_h)*groups+d/32];}red[tid]=sc;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]=fmaxf(red[tid],red[tid+z]);__syncthreads();}float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<=pos?__expf(sc-nm):0.0f;pr[tid]=pv;red[tid]=pv;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]+=red[tid+z];__syncthreads();}li=li*corr+red[0];for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++){size_t vi=(size_t)(ts+t)*value_stride+kv_h*(head_dim/2)+d/2;a+=pr[t]*q4_cache_to_float(vc,vi,vs[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32],d);}acc[d]=a;}mi=nm;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=NT)out[h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"/* Q8K/Q4V decode with warp-local reductions.  The reference kernel performs\n"
" * two full 256-thread shared-memory reductions per cache tile; this keeps\n"
" * the same one-key-per-thread mapping but reduces each warp with shuffles. */\n"
"__global__ void attn_decode_q8q4_warpred(float *out, const float *q, const signed char *kc, const unsigned char *vc, const float *ks, const float *vs, int n_heads, int n_kv_heads, int head_dim, int kv_dim, int value_stride, const int *pos_p, float scale) {\n"
"    extern __shared__ float smem[];int h=blockIdx.x;if(h>=n_heads)return;int kv_h=h/(n_heads/n_kv_heads),pos=*pos_p,tid=threadIdx.x,NT=blockDim.x,lane=tid&31,warp=tid>>5,groups=(head_dim+31)/32;\n"
"    float *qv=smem,*acc=qv+head_dim,*pr=acc+head_dim,*red=pr+NT;const float *qh=q+(size_t)h*head_dim;\n"
"    for(int d=tid;d<head_dim;d+=NT){qv[d]=qh[d]*scale;acc[d]=0.0f;}__syncthreads();float mi=-1e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=NT){int kp=ts+tid,tn=pos-ts+1;if(tn>NT)tn=NT;float sc=-1e30f;if(kp<=pos){const signed char *kr=kc+(size_t)kp*kv_dim+kv_h*head_dim;for(int d=0;d<head_dim;d++)sc+=qv[d]*(float)kr[d]*ks[((size_t)kp*n_kv_heads+kv_h)*groups+d/32];}\n"
"      float mx=sc;for(int z=16;z;z>>=1)mx=fmaxf(mx,__shfl_down(mx,z));if(lane==0)red[warp]=mx;__syncthreads();\n"
"      if(warp==0){mx=tid<NT/32?red[tid]:-1e30f;for(int z=16;z;z>>=1)mx=fmaxf(mx,__shfl_down(mx,z));if(tid==0)red[0]=mx;}__syncthreads();\n"
"      float nm=red[0],corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<=pos?__expf(sc-nm):0.0f;pr[tid]=pv;float sm=pv;for(int z=16;z;z>>=1)sm+=__shfl_down(sm,z);if(lane==0)red[warp]=sm;__syncthreads();\n"
"      if(warp==0){sm=tid<NT/32?red[tid]:0.0f;for(int z=16;z;z>>=1)sm+=__shfl_down(sm,z);if(tid==0)red[0]=sm;}__syncthreads();\n"
"      li=li*corr+red[0];for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++){size_t vi=(size_t)(ts+t)*value_stride+kv_h*(head_dim/2)+d/2;a+=pr[t]*q4_cache_to_float(vc,vi,vs[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32],d);}acc[d]=a;}mi=nm;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=NT)out[h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"/* Split-KV Q8K/Q4V decode. Each block reduces one sequence segment and\n"
" * writes (max,sum,value) partials; a second kernel combines the segments.\n"
" * This exposes long-context parallelism that the one-block-per-head path\n"
" * cannot use. */\n"
"__global__ void attn_decode_q8q4_split(float *partial, const float *q, const signed char *kc, const unsigned char *vc, const float *ks, const float *vs, int n_heads, int n_kv_heads, int head_dim, int kv_dim, int value_stride, const int *pos_p, float scale, int splits, int chunk) {\n"
"    extern __shared__ float smem[];int h=blockIdx.x,sp=blockIdx.y;if(h>=n_heads||sp>=splits)return;int tid=threadIdx.x,NT=blockDim.x,pos=*pos_p,start=sp*chunk,end=start+chunk;if(end>pos+1)end=pos+1;size_t base=((size_t)h*splits+sp)*(head_dim+2);\n"
"    if(start>pos){if(tid==0){partial[base]=-1e30f;partial[base+1]=0.0f;}return;}\n"
"    int kv_h=h/(n_heads/n_kv_heads),groups=(head_dim+31)/32;float *qv=smem,*acc=qv+head_dim,*pr=acc+head_dim,*red=pr+NT;const float *qh=q+(size_t)h*head_dim;\n"
"    for(int d=tid;d<head_dim;d+=NT){qv[d]=qh[d]*scale;acc[d]=0.0f;}__syncthreads();float mi=-1e30f,li=0.0f;\n"
"    for(int ts=start;ts<end;ts+=NT){int kp=ts+tid,tn=end-ts;if(tn>NT)tn=NT;float sc=-1e30f;if(kp<end){const signed char *kr=kc+(size_t)kp*kv_dim+kv_h*head_dim;for(int d=0;d<head_dim;d++)sc+=qv[d]*(float)kr[d]*ks[((size_t)kp*n_kv_heads+kv_h)*groups+d/32];}\n"
"      red[tid]=sc;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]=fmaxf(red[tid],red[tid+z]);__syncthreads();}float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<end?__expf(sc-nm):0.0f;pr[tid]=pv;red[tid]=pv;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]+=red[tid+z];__syncthreads();}\n"
"      li=li*corr+red[0];for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++){size_t vi=(size_t)(ts+t)*value_stride+kv_h*(head_dim/2)+d/2;a+=pr[t]*q4_cache_to_float(vc,vi,vs[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32],d);}acc[d]=a;}mi=nm;__syncthreads();}\n"
"    partial[base]=mi;partial[base+1]=li;for(int d=tid;d<head_dim;d+=NT)partial[base+2+d]=acc[d];\n"
"}\n"
"/* Split-KV attention variant using llama.cpp-style Q8 query quantization and\n"
" * DP4A for Q8K dot products. Query scales are per 32-element group. */\n"
"__global__ void attn_decode_q8q4_split_dp4a(float *partial, const signed char *q8, const float *qscale, const signed char *kc, const unsigned char *vc, const float *ks, const float *vs, int n_heads, int n_kv_heads, int head_dim, int kv_dim, int value_stride, const int *pos_p, float scale, int splits, int chunk) {\n"
"    extern __shared__ float smem[];int h=blockIdx.x,sp=blockIdx.y;if(h>=n_heads||sp>=splits)return;int tid=threadIdx.x,NT=blockDim.x,pos=*pos_p,start=sp*chunk,end=start+chunk;if(end>pos+1)end=pos+1;size_t base=((size_t)h*splits+sp)*(head_dim+2);\n"
"    if(start>pos){if(tid==0){partial[base]=-1e30f;partial[base+1]=0.0f;}return;}\n"
"    int kv_h=h/(n_heads/n_kv_heads),groups=(head_dim+31)/32;float *acc=smem,*pr=acc+head_dim,*red=pr+NT;const signed char *qh=q8+(size_t)h*head_dim;const float *qsc=qscale+(size_t)h*groups;\n"
"    for(int d=tid;d<head_dim;d+=NT)acc[d]=0.0f;__syncthreads();float mi=-1e30f,li=0.0f;\n"
"    for(int ts=start;ts<end;ts+=NT){int kp=ts+tid,tn=end-ts;if(tn>NT)tn=NT;float sc=-1e30f;if(kp<end){const signed char *kr=kc+(size_t)kp*kv_dim+kv_h*head_dim;float dot=0.0f;for(int g=0;g<groups;g++){const int *qa=(const int *)(qh+g*32);const int *ka=(const int *)(kr+g*32);int z=0;for(int j=0;j<8;j++)z=dp4a_hw(qa[j],ka[j],z);dot+=(float)z*qsc[g]*ks[((size_t)kp*n_kv_heads+kv_h)*groups+g];}sc=dot*scale;}red[tid]=sc;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]=fmaxf(red[tid],red[tid+z]);__syncthreads();}float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<end?__expf(sc-nm):0.0f;pr[tid]=pv;red[tid]=pv;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]+=red[tid+z];__syncthreads();}li=li*corr+red[0];for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++){size_t vi=(size_t)(ts+t)*value_stride+kv_h*(head_dim/2)+d/2;a+=pr[t]*q4_cache_to_float(vc,vi,vs[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32],d);}acc[d]=a;}mi=nm;__syncthreads();}\n"
"    partial[base]=mi;partial[base+1]=li;for(int d=tid;d<head_dim;d+=NT)partial[base+2+d]=acc[d];\n"
"}\n"
"__global__ void attn_decode_q8q4_split_combine(float *out, const float *partial, int n_heads, int head_dim, int splits) {\n"
"    int h=blockIdx.x,tid=threadIdx.x;if(h>=n_heads)return;extern __shared__ float red[];size_t stride=head_dim+2;float mx=-1e30f;if(tid==0){for(int sp=0;sp<splits;sp++){float v=partial[((size_t)h*splits+sp)*stride];mx=fmaxf(mx,v);}red[0]=mx;}__syncthreads();mx=red[0];\n"
"    if(tid==0){float den=0.0f;for(int sp=0;sp<splits;sp++){size_t b=((size_t)h*splits+sp)*stride;float m=partial[b];if(m>-1e29f)den+=partial[b+1]*__expf(m-mx);}red[0]=den;}__syncthreads();float den=red[0];for(int d=tid;d<head_dim;d+=blockDim.x){float num=0.0f;for(int sp=0;sp<splits;sp++){size_t b=((size_t)h*splits+sp)*stride;float m=partial[b];if(m>-1e29f)num+=partial[b+2+d]*__expf(m-mx);}out[(size_t)h*head_dim+d]=den>0.0f?num/den:0.0f;}\n"
"}\n"
"/* Vector-Q4V split decode, adapted from llama.cpp's fattn-vec layout.\n"
" * One lane owns two adjacent value channels, so a packed Q4 byte is read\n"
" * once for both outputs.  QK remains the exact DP4A path; only the V phase\n"
" * changes its lane mapping.  This is deliberately opt-in pending parity. */\n"
"__global__ void attn_decode_q8q4_split_dp4a_vecv(float *partial, const signed char *q8, const float *qscale, const signed char *kc, const unsigned char *vc, const float *ks, const float *vs, int n_heads, int n_kv_heads, int head_dim, int kv_dim, int value_stride, const int *pos_p, float scale, int splits, int chunk) {\n"
"    extern __shared__ float smem[];int h=blockIdx.x,sp=blockIdx.y,tid=threadIdx.x,NT=blockDim.x,pos=*pos_p;\n"
"    if(h>=n_heads||sp>=splits)return;int start=sp*chunk,end=start+chunk;if(end>pos+1)end=pos+1;\n"
"    size_t base=((size_t)h*splits+sp)*(head_dim+2);if(start>pos){if(tid==0){partial[base]=-1e30f;partial[base+1]=0.0f;}return;}\n"
"    int groups=(head_dim+31)/32;float *pr=smem,*red=pr+NT;const signed char *qh=q8+(size_t)h*head_dim;\n"
"    float mi=-1e30f,li=0.0f,a0=0.0f,a1=0.0f;\n"
"    for(int ts=start;ts<end;ts+=NT){int kp=ts+tid,tn=end-ts;if(tn>NT)tn=NT;float sc=-1e30f;\n"
"        if(kp<end){const signed char *kr=kc+(size_t)kp*kv_dim+(h/(n_heads/n_kv_heads))*head_dim;float dot=0.0f;\n"
"            #pragma unroll\n"
"            for(int g=0;g<groups;g++){const int *qa=(const int *)(qh+g*32);const int *ka=(const int *)(kr+g*32);int z=0;\n"
"                #pragma unroll\n"
"                for(int j=0;j<8;j++)z=dp4a_hw(qa[j],ka[j],z);dot+=(float)z*qscale[(size_t)h*groups+g]*ks[((size_t)kp*n_kv_heads+h/(n_heads/n_kv_heads))*groups+g];}sc=dot*scale;}\n"
"        red[tid]=sc;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]=fmaxf(red[tid],red[tid+z]);__syncthreads();}\n"
"        float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<end?__expf(sc-nm):0.0f;pr[tid]=pv;red[tid]=pv;__syncthreads();\n"
"        for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]+=red[tid+z];__syncthreads();}li=li*corr+red[0];\n"
"        if(tid<head_dim/2){int d=tid*2;float b0=a0*corr,b1=a1*corr;int kv_h=h/(n_heads/n_kv_heads);\n"
"            #pragma unroll 4\n"
"            for(int t=0;t<tn;t++){size_t vi=(size_t)(ts+t)*value_stride+kv_h*(head_dim/2)+tid;unsigned char p=vc[vi];\n"
"                float sv=vs[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32];int q0=(int)(p&15)-8,q1=(int)(p>>4)-8;b0+=pr[t]*((float)q0*sv);b1+=pr[t]*((float)q1*sv);}a0=b0;a1=b1;}\n"
"        mi=nm;__syncthreads();}\n"
"    if(tid<head_dim/2){partial[base]=mi;partial[base+1]=li;partial[base+2+tid*2]=a0;partial[base+3+tid*2]=a1;}\n"
"}\n"
"__global__ void attn_prefill_flash_q8q4(float *out, const float *q, const signed char *kc, const unsigned char *vc, const float *ks, const float *vs, int n_heads, int n_kv_heads, int head_dim, int kv_dim, int value_stride, int M, int position_start, float scale) {\n"
"    int h=blockIdx.x,m=blockIdx.y;if(h>=n_heads||m>=M)return;int kv_h=h/(n_heads/n_kv_heads),pos=position_start+m,tid=threadIdx.x,NT=blockDim.x,groups=(head_dim+31)/32;extern __shared__ float smem[];float *qv=smem,*acc=qv+head_dim,*pr=acc+head_dim,*red=pr+NT;const float *qh=q+(size_t)m*n_heads*head_dim+h*head_dim;for(int d=tid;d<head_dim;d+=NT){qv[d]=qh[d]*scale;acc[d]=0.0f;}__syncthreads();float mi=-1e30f,li=0.0f;for(int ts=0;ts<=pos;ts+=NT){int kp=ts+tid,tn=pos-ts+1;if(tn>NT)tn=NT;float sc=-1e30f;if(kp<=pos){const signed char *kr=kc+(size_t)kp*kv_dim+kv_h*head_dim;for(int d=0;d<head_dim;d++)sc+=qv[d]*(float)kr[d]*ks[((size_t)kp*n_kv_heads+kv_h)*groups+d/32];}red[tid]=sc;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]=fmaxf(red[tid],red[tid+z]);__syncthreads();}float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<=pos?__expf(sc-nm):0.0f;pr[tid]=pv;red[tid]=pv;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]+=red[tid+z];__syncthreads();}li=li*corr+red[0];for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++){size_t vi=(size_t)(ts+t)*value_stride+kv_h*(head_dim/2)+d/2;a+=pr[t]*q4_cache_to_float(vc,vi,vs[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32],d);}acc[d]=a;}mi=nm;__syncthreads();}float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=NT)out[(size_t)m*n_heads*head_dim+h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"/* GQA8 I8 decode: one block handles one query head while eight lanes share\n"
" * each key dot product.  Qwen4's 12:1 GQA ratio makes the K/V reads the\n"
" * dominant decode bandwidth term; this preserves the scalar head layout but\n"
" * reduces the per-key dot-product work from 256 duplicate lanes to 8. */\n"
"__global__ void attn_decode_gqa8_i8(float *out, const float *q,\n"
"    const signed char *key_cache, const signed char *value_cache, const float *key_scale, const float *value_scale,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim, const int *pos_p, float scale, int fp8) {\n"
"    extern __shared__ float smem[]; int h=blockIdx.x;if(h>=n_heads)return;\n"
"    int kv_h=h/(n_heads/n_kv_heads),pos=*pos_p,tid=threadIdx.x,key=tid>>3,lane=tid&7,groups=(head_dim+31)/32;\n"
"    float *q_sh=smem,*acc=q_sh+head_dim,*prob=acc+head_dim,*red=prob+32;\n"
"    for(int d=tid;d<head_dim;d+=blockDim.x){q_sh[d]=q[h*head_dim+d]*scale;acc[d]=0.0f;}\n"
"    __syncthreads();float mi=-1e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=32){int tn=pos-ts+1;if(tn>32)tn=32;float sc=-1e30f;\n"
"      if(key<tn){const signed char *kr=key_cache+(size_t)(ts+key)*kv_dim+kv_h*head_dim;sc=0.0f;\n"
"        for(int d=lane;d<head_dim;d+=8)sc+=q_sh[d]*qkv_byte_to_float(kr[d],key_scale[((size_t)(ts+key)*n_kv_heads+kv_h)*groups+d/32],fp8);\n"
"        for(int z=4;z;z>>=1)sc+=__shfl_down(sc,z,8);}\n"
"      /* One eight-lane group owns each key. Only lane 0 has the completed\n"
"       * dot product; indexing red[] by tid retained keys 0..3 only because\n"
"       * the other lane-0 threads have tid >= 32. */\n"
"      if(tid<32)red[tid]=-1e30f;__syncthreads();\n"
"      if(lane==0 && key<tn)red[key]=sc;__syncthreads();\n"
"      for(int z=16;z;z>>=1){if(tid<z)red[tid]=fmaxf(red[tid],red[tid+z]);__syncthreads();}\n"
"      float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm);\n"
"      if(tid<32)prob[tid]=tid<tn?__expf(red[tid]-nm):0.0f;__syncthreads();\n"
"      if(tid<32)red[tid]=prob[tid];__syncthreads();\n"
"      for(int z=16;z;z>>=1){if(tid<z)red[tid]+=red[tid+z];__syncthreads();}\n"
"      li=li*corr+red[0];for(int d=tid;d<head_dim;d+=blockDim.x){float a=acc[d]*corr;\n"
"        for(int t=0;t<tn;t++)a+=prob[t]*qkv_byte_to_float(value_cache[(size_t)(ts+t)*kv_dim+kv_h*head_dim+d],value_scale[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32],fp8);acc[d]=a;}\n"
"      mi=nm;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=blockDim.x)out[h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"/* Warp-per-key I8 prefill variant: eight warps compute eight QK scores\n"
" * concurrently, avoiding redundant full-dot work. */\n"
"__global__ void attn_prefill_flash_i8_warp(float *out, const float *q,\n"
"    const signed char *key_cache, const signed char *value_cache, const float *key_scale, const float *value_scale,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim, int position_start, float scale, int fp8) {\n"
"    extern __shared__ float smem[]; int h=blockIdx.x,m=blockIdx.y;if(h>=n_heads)return;\n"
"    int kv_h=h/(n_heads/n_kv_heads),pos=position_start+m,tid=threadIdx.x,NT=blockDim.x,q_dim=n_heads*head_dim;\n"
"    int W=NT/32,warp=tid/32,lane=tid&31,groups=(head_dim+31)/32; float *qv=smem,*acc=qv+head_dim,*score=acc+head_dim,*prob=score+W,*tmp=prob+W;\n"
"    const float *qh=q+(size_t)m*q_dim+h*head_dim; for(int d=tid;d<head_dim;d+=NT){qv[d]=qh[d]*scale;acc[d]=0.0f;} __syncthreads();\n"
"    float mi=-1e30f,li=0.0f; for(int ts=0;ts<=pos;ts+=W){int kp=ts+warp,tn=pos-ts+1;if(tn>W)tn=W;float s=-1e30f;\n"
"      if(kp<=pos){const signed char *kr=key_cache+(size_t)kp*kv_dim+kv_h*head_dim;for(int d=lane;d<head_dim;d+=32)s+=qv[d]*qkv_byte_to_float(kr[d],key_scale[((size_t)kp*n_kv_heads+kv_h)*groups+d/32],fp8);for(int z=16;z;z>>=1)s+=__shfl_down(s,z);} if(!lane)score[warp]=s; __syncthreads();\n"
"      if(tid<W)prob[tid]=score[tid]; __syncthreads(); if(!tid){float mx=prob[0];for(int j=1;j<W;j++)mx=fmaxf(mx,prob[j]);tmp[0]=mx;} __syncthreads();\n"
"      float mx=tmp[0],corr=mi<-1e29f?0.0f:__expf(mi-mx);if(tid<W)prob[tid]=__expf(prob[tid]-mx);__syncthreads();if(!tid){float z=0.0f;for(int j=0;j<W;j++)z+=prob[j];tmp[0]=z;}__syncthreads();\n"
"      li=li*corr+tmp[0];for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int j=0;j<tn;j++)a+=prob[j]*qkv_byte_to_float(value_cache[(size_t)(ts+j)*kv_dim+kv_h*head_dim+d],value_scale[((size_t)(ts+j)*n_kv_heads+kv_h)*groups+d/32],fp8);acc[d]=a;}mi=mx;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=NT)out[(size_t)m*q_dim+h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"/* GQA4 warp-per-key I8 prefill.  A warp handles one key and four query\n"
" * heads (8 lanes/head), sharing the K row through LDS.  This removes the\n"
" * redundant K loads across Qwen4's 4-query-head GQA groups. */\n"
"__global__ void attn_prefill_flash_i8_gqa4_warp(float *out, const float *q,\n"
"    const signed char *key_cache, const signed char *value_cache, const float *key_scale, const float *value_scale,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim, int position_start, float scale, int fp8) {\n"
"    extern __shared__ float smem[]; int g=blockIdx.x,m=blockIdx.y,tid=threadIdx.x;\n"
"    int W=blockDim.x/32,warp=tid/32,lane=tid&31,hs=lane>>3,sl=lane&7,h=g*4+hs;\n"
"    int pos=position_start+m,q_dim=n_heads*head_dim,groups=(head_dim+31)/32;\n"
"    int kv_h=(g*4)/(n_heads/n_kv_heads);\n"
"    if(g*4>=n_heads || kv_h>=n_kv_heads)return;\n"
"    float *ks=smem,*score=ks+(size_t)W*head_dim,*prob=score+4*W,*aux=prob+4*W;\n"
"    float acc[32],mi=-1e30f,li=0.0f;for(int j=0;j<32;j++)acc[j]=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=W){int kp=ts+warp,tn=pos-ts+1;if(tn>W)tn=W;\n"
"      if(kp<=pos){const signed char *kr=key_cache+(size_t)kp*kv_dim+(size_t)kv_h*head_dim;for(int d=lane;d<head_dim;d+=32)ks[(size_t)warp*head_dim+d]=qkv_byte_to_float(kr[d],key_scale[((size_t)kp*n_kv_heads+kv_h)*groups+d/32],fp8);}\n"
"      __syncthreads(); float sc=-1e30f;int ah=h;\n"
"      if(kp<=pos && ah<n_heads){for(int d=sl;d<head_dim;d+=8)sc+=q[(size_t)m*q_dim+ah*head_dim+d]*ks[(size_t)warp*head_dim+d];}\n"
"      for(int z=4;z;z>>=1)sc+=__shfl_down(sc,z,8);if(!sl)score[hs*W+warp]=sc;__syncthreads();\n"
"      if(warp==0 && lane<4){float z=-1e30f;for(int w=0;w<W;w++)z=fmaxf(z,score[lane*W+w]);aux[lane]=fmaxf(mi,z);}\n"
"      __syncthreads();\n"
"      if(!sl)prob[hs*W+warp]=(kp<=pos && ah<n_heads)?__expf(score[hs*W+warp]-aux[hs]):0.0f;__syncthreads();\n"
"      if(warp==0 && lane<4){float z=0.0f;for(int w=0;w<W;w++)z+=prob[lane*W+w];aux[4+lane]=z;}\n"
"      __syncthreads();float corr=mi<-1e29f?0.0f:__expf(mi-aux[hs]);li=li*corr+aux[4+hs];\n"
"      for(int j=0;j<32;j++){int d=sl+8*j;if(d<head_dim){float a=acc[j]*corr;for(int t=0;t<tn;t++)a+=prob[hs*W+t]*qkv_byte_to_float(value_cache[(size_t)(ts+t)*kv_dim+(size_t)kv_h*head_dim+d],value_scale[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32],fp8);acc[j]=a;}}\n"
"      mi=aux[hs];__syncthreads();\n"
"    }\n"
"    if(h<n_heads){float inv=li>0.0f?1.0f/li:0.0f;for(int j=0;j<32;j++){int d=sl+8*j;if(d<head_dim)out[(size_t)m*q_dim+h*head_dim+d]=acc[j]*inv;}}\n"
"}\n"
"__global__ void attn_prefill_flash_i8(float *out, const float *q,\n"
"    const signed char *key_cache, const signed char *value_cache, const float *key_scale, const float *value_scale,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim, int position_start, float scale, int fp8) {\n"
"    extern __shared__ float smem[];int h=blockIdx.x,m=blockIdx.y;if(h>=n_heads)return;int kv_h=h/(n_heads/n_kv_heads),pos=position_start+m,tid=threadIdx.x,NT=blockDim.x,q_dim=n_heads*head_dim,groups=(head_dim+31)/32;\n"
"    float *q_sh=smem,*acc=q_sh+head_dim,*prob=acc+head_dim,*red=prob+NT;const float *qh=q+(size_t)m*q_dim+h*head_dim;\n"
"    for(int d=tid;d<head_dim;d+=NT){q_sh[d]=qh[d]*scale;acc[d]=0.0f;}__syncthreads();float mi=-1e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=NT){int kp=ts+tid,tn=pos-ts+1;if(tn>NT)tn=NT;float sc=-1e30f;if(kp<=pos){const signed char *kr=key_cache+(size_t)kp*kv_dim+kv_h*head_dim;sc=0.0f;for(int d=0;d<head_dim;d++)sc+=q_sh[d]*qkv_byte_to_float(kr[d],key_scale[((size_t)kp*n_kv_heads+kv_h)*groups+d/32],fp8);}\n"
"      red[tid]=sc;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]=fmaxf(red[tid],red[tid+z]);__syncthreads();}float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:__expf(mi-nm),pv=kp<=pos?__expf(sc-nm):0.0f;/* QWEN4_ATTN_MAX_READERS */ __syncthreads();prob[tid]=pv;red[tid]=pv;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]+=red[tid+z];__syncthreads();}\n"
"      li=li*corr;for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++)a+=prob[t]*qkv_byte_to_float(value_cache[(size_t)(ts+t)*kv_dim+kv_h*head_dim+d],value_scale[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d/32],fp8);acc[d]=a;}li+=red[0];mi=nm;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=NT)out[(size_t)m*q_dim+h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"__global__ void attn_prefill_flash_f16(float *out, const float *q,\n"
"    const half_raw *key_cache, const half_raw *value_cache,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_dim,\n"
"    int position_start, float scale) {\n"
"    extern __shared__ float smem[]; int h=blockIdx.x, m=blockIdx.y;\n"
"    if(h>=n_heads)return; int kv_h=h/(n_heads/n_kv_heads), pos=position_start+m;\n"
"    int tid=threadIdx.x, NT=blockDim.x, q_dim=n_heads*head_dim;\n"
"    float *q_sh=smem,*acc=q_sh+head_dim,*prob=acc+head_dim,*red=prob+NT;\n"
"    const float *qh=q+(size_t)m*q_dim+h*head_dim;\n"
"    for(int d=tid;d<head_dim;d+=NT){q_sh[d]=qh[d]*scale;acc[d]=0.0f;}\n"
"    __syncthreads(); float mi=-1e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=NT){ int kp=ts+tid, tn=pos-ts+1; if(tn>NT)tn=NT; float sc=-1e30f;\n"
"      if(kp<=pos){const half_raw *kr=key_cache+(size_t)kp*kv_dim+kv_h*head_dim;sc=0.0f;for(int d=0;d<head_dim;d++)sc+=q_sh[d]*half_to_float(kr[d]);}\n"
"      red[tid]=sc;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]=fmaxf(red[tid],red[tid+z]);__syncthreads();}\n"
"      float nm=fmaxf(mi,red[0]),corr=mi<-1e29f?0.0f:expf(mi-nm),pv=kp<=pos?expf(sc-nm):0.0f;\n"
"      /* QWEN4_ATTN_MAX_READERS */ __syncthreads();prob[tid]=pv;red[tid]=pv;__syncthreads();for(int z=NT/2;z;z>>=1){if(tid<z)red[tid]+=red[tid+z];__syncthreads();}\n"
"      li=li*corr+red[0];for(int d=tid;d<head_dim;d+=NT){float a=acc[d]*corr;for(int t=0;t<tn;t++)\n"
"        a+=prob[t]*half_to_float(value_cache[(size_t)(ts+t)*kv_dim+kv_h*head_dim+d]);acc[d]=a;}\n"
"      mi=nm;__syncthreads();}\n"
"    float inv=li>0.0f?1.0f/li:0.0f;for(int d=tid;d<head_dim;d+=NT)out[(size_t)m*q_dim+h*head_dim+d]=acc[d]*inv;\n"
"}\n"
"/* llama.cpp fattn-vec-shaped Q8/Q4 fallback.  Eight lanes own one KQ\n"
" * score, with half2 operands and v_dot2_f32_f16; the V update keeps the\n"
" * same online-softmax state but uses one output channel per thread.  This\n"
" * is opt-in while its full-model numerical trace is being compared. */\n"
"__global__ void attn_prefill_fattn_vec_f16(float *out, const half_raw *q,\n"
"    const half_raw *key_cache, const half_raw *value_cache,\n"
"    int n_heads, int n_kv_heads, int head_dim, int kv_len,\n"
"    int M, int position_start, float scale) {\n"
"    int h=blockIdx.x,m=blockIdx.y,tid=threadIdx.x,NT=blockDim.x;\n"
"    if(h>=n_heads||m>=M)return;\n"
"    int kv_h=h/(n_heads/n_kv_heads),pos=position_start+m,q_dim=n_heads*head_dim;\n"
"    extern __shared__ float sm[]; float *scores=sm,*prob=scores+32,*state=prob+32;\n"
"    float acc=0.0f; int d=tid;\n"
"    const half_raw *qh=q+(size_t)m*q_dim+h*head_dim;\n"
"    const __half2 *q2=(const __half2 *)qh;\n"
"    __half2 scale2=__halves2half2(__float2half(scale),__float2half(scale));\n"
"    float mi=-1.0e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=32){\n"
"        int group=tid>>3,lane=tid&7,key=ts+group,tn=pos-ts+1;\n"
"        if(tn>32)tn=32; float s=group<tn?0.0f:-1.0e30f;\n"
"        if(group<tn){\n"
"            const __half2 *k2=(const __half2 *)(key_cache+((size_t)kv_h*kv_len+key)*head_dim);\n"
"            for(int k0=0;k0<head_dim/2;k0+=8*4) for(int j=0;j<4;j++){\n"
"                __half2 qv=__hmul2(q2[k0+lane*4+j],scale2);\n"
"                __half2 kv=k2[k0+lane*4+j];\n"
"                asm volatile(\"v_dot2_f32_f16 %0, %1, %2, %0\"\n"
"                    : \"+v\"(s) : \"v\"(kv), \"v\"(qv));\n"
"            }\n"
"        }\n"
"        for(int off=4;off;off>>=1)s+=__shfl_down(s,off,8);\n"
"        if(lane==0)scores[group]=s;\n"
"        __syncthreads();\n"
"        if(tid==0){\n"
"            float mx=mi; for(int t=0;t<tn;t++)mx=fmaxf(mx,scores[t]);\n"
"            float corr=mi<-1.0e29f?0.0f:expf(mi-mx),sum=0.0f;\n"
"            for(int t=0;t<32;t++){float p=t<tn?expf(scores[t]-mx):0.0f;prob[t]=p;sum+=p;}\n"
"            mi=mx; li=li*corr+sum; state[0]=li; state[1]=corr;\n"
"        }\n"
"        __syncthreads();\n"
"        if(d<head_dim){float a=acc*state[1];\n"
"            for(int t=0;t<tn;t++){const half_raw *vr=value_cache+((size_t)kv_h*kv_len+ts+t)*head_dim;\n"
"                a+=prob[t]*half_to_float(vr[d]);}\n"
"            acc=a;}\n"
"        __syncthreads();\n"
"    }\n"
"    if(d<head_dim){float li_final=state[0];out[(size_t)m*q_dim+h*head_dim+d]=li_final>0.0f?acc/li_final:0.0f;}\n"
"}\n"
"/* Direct llama.cpp-style Q8_1-Q8_0/Q4_0 attention.  Unlike the packed-F16\n"
" * fallback above, this keeps Q8 query integers and performs the KQ dot as\n"
" * signed integer products times the two FP32 block scales.  It is an A/B\n"
" * kernel until its V accumulation is matched to llama.cpp's half2 path. */\n"
"__global__ void attn_prefill_fattn_vec_q8q4(float *out, const signed char *q8,\n"
"    const float *qscale, const signed char *kc, const unsigned char *vc,\n"
"    const float *ks, const float *vs, int n_heads, int n_kv_heads,\n"
"    int head_dim, int kv_dim, int value_stride, int M, int position_start) {\n"
"    int h=blockIdx.x,m=blockIdx.y,tid=threadIdx.x;\n"
"    if(h>=n_heads||m>=M)return;\n"
"    int kv_h=h/(n_heads/n_kv_heads),pos=position_start+m,lane=tid&7,key=tid>>3;\n"
"    int groups=head_dim/32,q_dim=n_heads*head_dim;\n"
"    extern __shared__ float sm[]; float *score=sm,*prob=score+16;\n"
"    float *state=prob+16; float a0=0.0f,a1=0.0f;\n"
"    const signed char *qh=q8+((size_t)m*n_heads+h)*head_dim;\n"
"    const float *qds=qscale+((size_t)m*n_heads+h)*groups;\n"
"    float mi=-1.0e30f,li=0.0f;\n"
"    for(int ts=0;ts<=pos;ts+=16){\n"
"        int tn=pos-ts+1; if(tn>16)tn=16; float dot=0.0f;\n"
"        if(key<tn){\n"
"            const signed char *kh=kc+(size_t)(ts+key)*kv_dim+kv_h*head_dim;\n"
"            for(int g=0;g<groups;g++){\n"
"                const int *qa=(const int *)(qh+g*32+lane*4);\n"
"                const int *ka=(const int *)(kh+g*32+lane*4);\n"
"                int z=0; z=dp4a_hw(*qa,*ka,z);\n"
"                dot+=(float)z*qds[g]*ks[((size_t)(ts+key)*n_kv_heads+kv_h)*groups+g];\n"
"            }\n"
"            for(int s=4;s;s>>=1)dot+=__shfl_down(dot,s,8);\n"
"        }\n"
"        if(lane==0)score[key]=key<tn?dot:-1.0e30f;\n"
"        __syncthreads();\n"
"        if(tid==0){ float mx=mi; for(int t=0;t<tn;t++)mx=fmaxf(mx,score[t]);\n"
"            float corr=mi<-1.0e29f?0.0f:expf(mi-mx),sum=0.0f;\n"
"            for(int t=0;t<16;t++){float p=t<tn?expf(score[t]-mx):0.0f;prob[t]=p;sum+=p;}\n"
"            mi=mx; li=li*corr+sum; state[0]=li; state[1]=corr; }\n"
"        __syncthreads();\n"
"        int d0=tid,d1=tid+128;\n"
"        if(d0<head_dim||d1<head_dim){\n"
"            float b0=d0<head_dim?half_to_float(f32_to_f16_bits(a0*state[1])):0.0f;\n"
"            float b1=d1<head_dim?half_to_float(f32_to_f16_bits(a1*state[1])):0.0f;\n"
"            for(int t=0;t<tn;t++){\n"
"                const unsigned char *vv=vc+(size_t)(ts+t)*value_stride+kv_h*(head_dim/2);\n"
"                float p=half_to_float(f32_to_f16_bits(prob[t])),s0=vs[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d0/32];\n"
"                if(d0<head_dim){float z=half_to_float(f32_to_f16_bits((float)(((d0&1)?(vv[d0/2]>>4):(vv[d0/2]&15))-8)*s0));\n"
"                    b0=half_to_float(f32_to_f16_bits(b0+p*z));}\n"
"                if(d1<head_dim){float s1=vs[((size_t)(ts+t)*n_kv_heads+kv_h)*groups+d1/32];\n"
"                    float z=half_to_float(f32_to_f16_bits((float)(((d1&1)?(vv[d1/2]>>4):(vv[d1/2]&15))-8)*s1));\n"
"                    b1=half_to_float(f32_to_f16_bits(b1+p*z));}\n"
"            }\n"
"            a0=b0; a1=b1;\n"
"        }\n"
"        __syncthreads();\n"
"    }\n"
"    /* The online-softmax denominator is maintained by tid 0 and mirrored\n"
"     * through shared state; every value-owning thread must use that shared\n"
"     * final value rather than its private, untouched li. */\n"
"    if(tid<head_dim){float inv=state[0]>0.0f?1.0f/state[0]:0.0f;\n"
"        if(tid<head_dim)out[(size_t)m*q_dim+h*head_dim+tid]=a0*inv;\n"
"        if(tid+128<head_dim)out[(size_t)m*q_dim+h*head_dim+tid+128]=a1*inv;}\n"
"}\n"
"/* Repack batch buffer from compact per-layer stride to padded max stride.\n"
" * dst [M * dst_stride] = src [M * src_stride], copying n_per_row elements per row. */\n"
"__global__ void repack_batch_f32(float *dst, const float *src,\n"
"    int M, int n_per_row, int src_stride, int dst_stride) {\n"
"    int gid = blockIdx.x * blockDim.x + threadIdx.x;\n"
"    int total = M * n_per_row;\n"
"    if (gid >= total) return;\n"
"    int row = gid / n_per_row;\n"
"    int col = gid - row * n_per_row;\n"
"    dst[(size_t)row * dst_stride + col] = src[(size_t)row * src_stride + col];\n"
"}\n"
"\n"
"/* Qwen4 PLE: a per-HC-stream signed-square-root dot gate. */\n"
"__global__ void ple_gate_f32(float *gate, const float *key, const float *query, int n_embd) {\n"
"    extern __shared__ float red[]; int h = blockIdx.x, tid = threadIdx.x;\n"
"    float s = 0.0f; const float *k = key + (size_t)h*n_embd;\n"
"    const float *q = query + (size_t)h*n_embd;\n"
"    for (int i=tid; i<n_embd; i+=blockDim.x) s += k[i]*q[i];\n"
"    red[tid]=s; __syncthreads();\n"
"    for (int z=blockDim.x/2; z; z>>=1) { if(tid<z) red[tid]+=red[tid+z]; __syncthreads(); }\n"
"    if (!tid) { float x=red[0]/sqrtf((float)n_embd); float a=sqrtf(fmaxf(fabsf(x),1e-6f));\n"
"                if(x<0.0f)a=-a; gate[h]=1.0f/(1.0f+expf(-a)); }\n"
"}\n"
"/* Broadcast the PLE value over HC streams and apply each stream's gate. */\n"
"__global__ void ple_broadcast_gate_f32(float *out, const float *value, const float *gate, int n_embd, int streams) {\n"
"    int i=blockIdx.x*blockDim.x+threadIdx.x, n=n_embd*streams; if(i<n) out[i]=value[i % n_embd]*gate[i/n_embd];\n"
"}\n"
"/* Causal depthwise PLE convolution. state is chronological [hist, channels]. */\n"
"__global__ void ple_conv_dilated_silu_f32(float *out, float *state, const float *in, const float *w,\n"
"                                           int channels, int kern, int dilation) {\n"
"    int c=blockIdx.x*blockDim.x+threadIdx.x; if(c>=channels)return; int hist=(kern-1)*dilation; float s=0.0f;\n"
"    for(int k=0;k<kern;k++){ int back=(kern-1-k)*dilation; float x=back?state[(size_t)(hist-back)*channels+c]:in[c]; s+=w[(size_t)c*kern+k]*x; }\n"
"    out[c]=s/(1.0f+expf(-s));\n"
"    for(int t=0;t<hist-1;t++) state[(size_t)t*channels+c]=state[(size_t)(t+1)*channels+c];\n"
"    if(hist) state[(size_t)(hist-1)*channels+c]=in[c];\n"
"}\n"
"__global__ void add3_f32(float *dst, const float *a, const float *b, int n) {\n"
"    int i=blockIdx.x*blockDim.x+threadIdx.x; if(i<n) dst[i]+=a[i]+b[i];\n"
"}\n"
"\n"
"} /* extern \"C\" */\n"
;

/* ======================================================================== */
/* Error checking macros                                                    */
/* ======================================================================== */

#define CHECK_HIP(call) do { \
    hipError_t err = (call); \
    if (err != hipSuccess) { \
        const char *errStr = "unknown"; \
        if (hipGetErrorString) hipGetErrorString(err, &errStr); \
        fprintf(stderr, "HIP error at %s:%d: %s (code %d)\n", \
                __FILE__, __LINE__, errStr, (int)err); \
        return -1; \
    } \
} while(0)

/* hipMalloc takes void **; keep typed device pointers warning-clean without
 * relying on permissive C conversion rules. */
#define CHECK_HIP_MALLOC(ptr, bytes) \
    CHECK_HIP(hipMalloc((void **)(void *)(ptr), (bytes)))

#define CHECK_HIP_NULL(call) do { \
    hipError_t err = (call); \
    if (err != hipSuccess) { \
        const char *errStr = "unknown"; \
        if (hipGetErrorString) hipGetErrorString(err, &errStr); \
        fprintf(stderr, "HIP error at %s:%d: %s (code %d)\n", \
                __FILE__, __LINE__, errStr, (int)err); \
        return NULL; \
    } \
} while(0)

#define CHECK_HIP_VOID(call) do { \
    hipError_t err = (call); \
    if (err != hipSuccess) { \
        const char *errStr = "unknown"; \
        if (hipGetErrorString) hipGetErrorString(err, &errStr); \
        fprintf(stderr, "HIP error at %s:%d: %s (code %d)\n", \
                __FILE__, __LINE__, errStr, (int)err); \
        return; \
    } \
} while(0)

/* ======================================================================== */
/* Runner state                                                             */
/* ======================================================================== */

typedef struct {
    void *k_weight;
    void *v_weight;
    void *q_a_weight;
    void *q_b_weight;
    void *kv_a_weight;
    void *q_a_norm;
    void *kv_a_norm;
    void *out_weight;
    void *indexer_k_weight;
    void *indexer_gate_weight;
    void *indexer_q_weight;
    void *indexer_proj_weight;
    size_t k_stride;
    size_t v_stride;
    int q_a_type;
    int q_b_type;
    int kv_a_type;
    int indexer_k_type;
    int indexer_gate_type;
    int indexer_q_type;
    int indexer_proj_type;
    int out_type;
    int q_ready;
    int indexer_ready;
    int ready;
} glm5next_dsa_gpu_cache;

static void glm5next_hip_dsa_cache_free(glm5next_dsa_gpu_cache *cache) {
    if (!cache) return;
    if (cache->k_weight) hipFree(cache->k_weight);
    if (cache->v_weight) hipFree(cache->v_weight);
    if (cache->q_a_weight) hipFree(cache->q_a_weight);
    if (cache->q_b_weight) hipFree(cache->q_b_weight);
    if (cache->kv_a_weight) hipFree(cache->kv_a_weight);
    if (cache->q_a_norm) hipFree(cache->q_a_norm);
    if (cache->kv_a_norm) hipFree(cache->kv_a_norm);
    if (cache->out_weight) hipFree(cache->out_weight);
    if (cache->indexer_k_weight) hipFree(cache->indexer_k_weight);
    if (cache->indexer_gate_weight) hipFree(cache->indexer_gate_weight);
    if (cache->indexer_q_weight) hipFree(cache->indexer_q_weight);
    if (cache->indexer_proj_weight) hipFree(cache->indexer_proj_weight);
    memset(cache, 0, sizeof(*cache));
}

typedef struct {
    void *d[6];                 /* dx, dq, dk, dg, diq, diw */
    float *key, *gate, *iq, *iw;
    float *kw, *kb, *ape, *pool;
    size_t pool_floats;
    int ready;
} glm5next_dsa_indexer_scratch;

typedef struct {
    void *d[11];                /* DSA projection, attention, and output scratch */
    size_t seq_capacity;
    int ready;
} glm5next_dsa_decode_scratch;

typedef struct {
    void *matrix[9];
    void *conv[3];
    void *dt_bias;
    void *a;
    void *norm;
    int types[9];
    int ready;
} glm5next_kda_gpu_cache;

typedef struct {
    void *fn;
    void *base;
    void *scale;
    float *base_f;
    float *scale_f;
    float *logits;
    int type;
    int ready;
} glm5next_mhc_gpu_cache;

typedef struct {
    void *state;
    void *conv[3];
    int ready;
} glm5next_kda_state_gpu;

typedef struct {
    void *weight;
    float *bias;
    int type;
    int ready;
} glm5next_moe_router_cache;

typedef struct {
    void *gate;
    void *up;
    void *down;
    int gate_type;
    int up_type;
    int down_type;
    int ready;
} glm5next_dense_gpu_cache;

/* GLM5Next's routed experts are selected independently at every layer.  Keep
 * a bounded global set of complete (gate, up, down) expert matrices on the
 * device and evict the least-recently-used entry when the budget is full.
 * Entries are deliberately lazy: a small card can still run with the
 * streaming fallback if even one expert does not fit. */
typedef struct {
    int layer;
    int expert;
    uint64_t age;
    size_t bytes;
    void *gate;
    void *up;
    void *down;
    int gate_type;
    int up_type;
    int down_type;
    size_t gate_capacity;
    size_t up_capacity;
    size_t down_capacity;
    int pooled_down;
    int valid;
} glm5next_moe_resident_slot;

/* Mapped-host mode already has a down-only pool.  Keep a separate pool for
 * routed gate/up matrices so it can be enabled without changing the LRU
 * ownership rules of the complete-expert cache. */
typedef struct {
    int layer;
    int expert;
    uint64_t age;
    unsigned char *gate;
    unsigned char *up;
    int gate_type;
    int up_type;
    int valid;
} glm5next_moe_gu_slot;

/* Per-layer GPU weight pointers */
typedef struct {
    void *attn_norm_w;    /* F32 [n_embd] */
    void *attn_q_w;       /* F16 [n_rows * n_cols] */
    void *attn_k_w;
    void *attn_v_w;
    void *attn_q_bias;    /* F32 [n_embd] Q projection bias (Qwen2.5-VL) */
    void *attn_k_bias;    /* F32 [kv_dim] K projection bias */
    void *attn_v_bias;    /* F32 [kv_dim] V projection bias */
    void *attn_q_norm_w;  /* F32 [head_dim] */
    void *attn_k_norm_w;  /* F32 [head_dim] */
    void *attn_output_w;  /* F16 */
    void *ffn_norm_w;     /* F32 [n_embd] */
    void *ffn_gate_w;     /* F16 */
    void *ffn_up_w;       /* F16 */
    void *ffn_down_w;     /* F16 */

    /* BF16 copies for hipBLASLt prefill GEMMs (Phase 2). NULL if not converted. */
    void *attn_q_w_bf16;
    void *attn_k_w_bf16;
    void *attn_v_w_bf16;
    void *attn_output_w_bf16;
    void *ffn_gate_w_bf16;
    void *ffn_up_w_bf16;
    void *ffn_down_w_bf16;

    /* Dimensions for matvec */
    int attn_q_rows, attn_q_cols;
    int attn_k_rows, attn_k_cols;
    int attn_v_rows, attn_v_cols;
    int attn_output_rows, attn_output_cols;
    int ffn_gate_rows, ffn_gate_cols;
    int ffn_up_rows, ffn_up_cols;
    int ffn_down_rows, ffn_down_cols;

    int has_qk_norm;

    /* Weight types */
    int attn_q_type, attn_k_type, attn_v_type, attn_output_type;
    int ffn_gate_type, ffn_up_type, ffn_down_type;

    /* MoE fields */
    int state_index;             /* explicit cache/accounting slot, including NextN */
    int is_moe;
    void *moe_gate_w;
    void *moe_gate_w_bf16;        /* bf16 router weights (fused decode) */
    void *moe_shared_gate_w_bf16;
    int moe_gate_rows, moe_gate_cols;
    void *moe_gate_exps_w;
    void *moe_up_exps_w;
    void *moe_down_exps_w;
    int moe_gate_exps_type, moe_up_exps_type, moe_down_exps_type;
    int moe_exp_rows_gu, moe_exp_cols_gu;
    int moe_exp_rows_d, moe_exp_cols_d;
    size_t moe_exp_stride_gu;
    size_t moe_exp_stride_d;
    const void *moe_gate_exps_host;
    const void *moe_up_exps_host;
    const void *moe_down_exps_host;
    void *moe_gate_exps_mapped;
    void *moe_up_exps_mapped;
    void *moe_down_exps_mapped;
    int moe_gate_host_registered, moe_up_host_registered, moe_down_host_registered;
    void *moe_cache_gate;
    void *moe_cache_up;
    void *moe_cache_down;
    int *moe_cache_ids;
    uint64_t *moe_cache_age;    /* host LRU timestamp for routed experts */
    uint32_t *moe_cache_freq;   /* host LFU count when requested */
    int *d_moe_cache_map;       /* device expert id -> resident cache slot */
    int moe_cache_slots;
    int moe_cache_next;
    int moe_pending_slot;
    int moe_pending_expert;
    size_t moe_cache_stride_gate;
    size_t moe_cache_stride_up;
    size_t moe_cache_stride_down;
    /* Request-local prefill history is intentionally separate from decode LRU. */
    uint32_t *moe_prefill_score;
    void *moe_shared_gate_w;
    void *moe_shared_ffn_gate_w;
    void *moe_shared_ffn_up_w;
    void *moe_shared_ffn_down_w;
    int moe_shared_gate_type, moe_shared_up_type, moe_shared_down_type;
    int moe_shared_gate_rows, moe_shared_gate_cols;
    int moe_shared_up_rows, moe_shared_up_cols;
    int moe_shared_down_rows, moe_shared_down_cols;

    /* SSM (Delta-Net) layer fields */
    int is_ssm;
    void *ssm_qkv_w;
    void *ssm_gate_w;
    void *ssm_alpha_w;
    void *ssm_beta_w;
    void *ssm_out_w;

    /* BF16 copies for hipBLASLt prefill GEMMs (Phase 2/3). NULL if not converted. */
    void *ssm_qkv_w_bf16;
    void *ssm_gate_w_bf16;
    void *ssm_alpha_w_bf16;
    void *ssm_beta_w_bf16;
    void *ssm_out_w_bf16;

    void *ssm_a;
    void *ssm_dt_bias;
    void *ssm_conv1d_w;
    void *ssm_norm_w;
    int ssm_qkv_type, ssm_gate_type, ssm_alpha_type, ssm_beta_type, ssm_out_type;
    int ssm_qkv_rows, ssm_qkv_cols;
    int ssm_gate_rows, ssm_gate_cols;
    int ssm_alpha_rows, ssm_alpha_cols;
    int ssm_beta_rows, ssm_beta_cols;
    int ssm_out_rows, ssm_out_cols;

    /* SSM persistent state */
    void *d_conv_state;
    void *d_recurrent_state;

    /* Qwen4 hyperconnection weights. */
    void *hc_attn_norm_w, *hc_attn_down_w, *hc_attn_up_w, *hc_attn_inject_w;
    void *hc_attn_down_w_bf16, *hc_attn_up_w_bf16;
    void *hc_ffn_norm_w,  *hc_ffn_down_w,  *hc_ffn_up_w,  *hc_ffn_inject_w;
    void *hc_ffn_down_w_bf16, *hc_ffn_up_w_bf16;
    int hc_attn_down_type, hc_attn_up_type, hc_attn_inject_type;
    int hc_ffn_down_type, hc_ffn_up_type, hc_ffn_inject_type;

    /* Qwen4 QSA indexer. */
    void *index_q_w, *index_k_w, *index_q_norm_w, *index_k_norm_w;
    int index_q_type, index_k_type;
    int qsa_ratio;
    void *d_index_cache;

    /* Qwen4 PLE (present only on metadata-selected layers). */
    void *ple_key_w, *ple_value_w, *ple_norm_key_w, *ple_norm_query_w;
    void *ple_norm_conv_w, *ple_conv1d_w;
    int ple_key_type, ple_value_type;
    int ple_key_rows, ple_key_cols, ple_value_rows, ple_value_cols;

    /* Gemma4 fields */
    int is_swa;                 /* 1 = sliding window attention layer */
    int shared_kv_source;       /* -1 = own KV, else layer index to share from */
    int local_kv_heads;         /* per-layer KV head count (may differ from r->n_kv_heads) */
    int local_head_dim;         /* head_dim_full or head_dim_swa */
    void *post_attn_norm_w;     /* F32 [n_embd] post-attention norm */
    void *post_ffw_norm_w;      /* F32 [n_embd] post-FFN norm */
    void *ple_inp_gate_w;       /* F32 [ple_dim, n_embd] PLE input gate */
    void *ple_proj_w;           /* F32 [n_embd, ple_dim] PLE projection */
    void *ple_post_norm_w;      /* F32 [n_embd] PLE post-projection norm */
    float layer_scale_val;      /* layer output scale (default 1.0) */
} hip_layer;

