#include "qwen4_ple_split_test.h"

/* Public API: accessors                                                    */
/* ======================================================================== */

/* Local block metadata for quant matvec kernels. ggml_type_info is a static
 * const in gguf_loader.h, only visible to translation units that define
 * GGUF_LOADER_IMPLEMENTATION, so the runner keeps the small table it needs. */
static int quant_matvec_block_info(int weight_type, int *blk_elems, int *blk_bytes) {
    if (!blk_elems || !blk_bytes) return -1;
    *blk_elems = 0;
    *blk_bytes = 0;
    switch (weight_type) {
        case GGML_TYPE_Q8_0:    *blk_elems = 32;  *blk_bytes = 36;  break;
        case GGML_TYPE_Q2_K:    *blk_elems = 256; *blk_bytes = 84;  break;
        case GGML_TYPE_Q3_K:    *blk_elems = 256; *blk_bytes = 110; break;
        case GGML_TYPE_Q4_K:    *blk_elems = 256; *blk_bytes = 144; break;
        case GGML_TYPE_Q5_K:    *blk_elems = 256; *blk_bytes = 176; break;
        case GGML_TYPE_Q6_K:    *blk_elems = 256; *blk_bytes = 210; break;
        case GGML_TYPE_Q4_0:    *blk_elems = 32;  *blk_bytes = 18;  break;
        case GGML_TYPE_Q4_1:    *blk_elems = 32;  *blk_bytes = 20;  break;
        case GGML_TYPE_Q5_0:    *blk_elems = 32;  *blk_bytes = 22;  break;
        case GGML_TYPE_Q5_1:    *blk_elems = 32;  *blk_bytes = 24;  break;
        case GGML_TYPE_IQ2_XXS: *blk_elems = 256; *blk_bytes = 66;  break;
        case GGML_TYPE_IQ2_XS:  *blk_elems = 256; *blk_bytes = 74;  break;
        case GGML_TYPE_IQ2_S:   *blk_elems = 256; *blk_bytes = 82;  break;
        case GGML_TYPE_IQ3_XXS: *blk_elems = 256; *blk_bytes = 98;  break;
        case GGML_TYPE_IQ3_S:   *blk_elems = 256; *blk_bytes = 110; break;
        case GGML_TYPE_IQ1_S:   *blk_elems = 256; *blk_bytes = 50;  break;
        case GGML_TYPE_IQ1_M:   *blk_elems = 256; *blk_bytes = 56;  break;
        case GGML_TYPE_IQ4_NL:  *blk_elems = 32;  *blk_bytes = 18;  break;
        case GGML_TYPE_IQ4_XS:  *blk_elems = 256; *blk_bytes = 136; break;
        case GGML_TYPE_TQ1_0:   *blk_elems = 256; *blk_bytes = 54;  break;
        case GGML_TYPE_TQ2_0:   *blk_elems = 256; *blk_bytes = 66;  break;
        default: return -1;
    }
    return 0;
}

static void fill_quant_matvec_inputs(unsigned char *h_mat, size_t mat_bytes,
                                     float *h_x, int n_cols, int weight_type) {
    unsigned s = 0xC0FFEEu ^ (unsigned)weight_type;
    for (size_t i = 0; i < mat_bytes; i++) {
        s ^= s << 13; s ^= s >> 17; s ^= s << 5;
        h_mat[i] = (unsigned char)s;
    }
    for (int i = 0; i < n_cols; i++) {
        s ^= s << 13; s ^= s >> 17; s ^= s << 5;
        h_x[i] = (((float)((s >> 8) & 0xFFFFFF) / 16777216.0f) - 0.5f) * 0.1f;
    }
}

int hip_llm_verify_moe_routing(hip_llm_runner *r, int n_experts, int n_used) {
    if (!r || n_experts <= 256 || n_experts > 512 || n_used <= 0 || n_used > 64)
        return -1;

    const int M = 8;
    size_t logits_bytes = (size_t)M * n_experts * sizeof(float);
    size_t route_bytes = (size_t)M * n_used * sizeof(int);
    size_t weight_bytes = (size_t)M * n_used * sizeof(float);
    float *h_logits = (float *)malloc(logits_bytes);
    int *h_idx = (int *)malloc(route_bytes);
    float *h_w = (float *)malloc(weight_bytes);
    int *h_ref_idx = (int *)malloc(route_bytes);
    float *h_ref_w = (float *)malloc(weight_bytes);
    if (!h_logits || !h_idx || !h_w || !h_ref_idx || !h_ref_w) {
        free(h_logits); free(h_idx); free(h_w); free(h_ref_idx); free(h_ref_w);
        return -2;
    }
    unsigned seed = 1234567u;
    for (int m = 0; m < M; m++) {
        float *row = h_logits + (size_t)m * n_experts;
        for (int e = 0; e < n_experts; e++) {
            seed = seed * 1664525u + 1013904223u;
            row[e] = m < 2 ? (float)e * 0.001f :
                     m == 2 ? 0.0f : m == 3 ? -(float)e * 0.001f :
                     (float)(seed >> 8) / 16777216.0f;
        }
        if (m == 0) {
            /* Selecting the upper candidate must not hide its paired lower
             * candidate on the following rank. The former fixture only
             * selected upper-half experts and missed this failure. */
            row[n_experts - 1] = 10.0f;
            row[n_experts - 1 - 256] = 9.0f;
        }
    }
    for (int m = 0; m < M; m++)
        moe_topk_softmax(h_logits + (size_t)m * n_experts, n_experts, n_used,
                         h_ref_idx + (size_t)m * n_used,
                         h_ref_w + (size_t)m * n_used);

    float *d_logits = NULL, *d_w = NULL;
    int *d_idx = NULL;
    int rc = 0;
    if (hipMalloc((void **)&d_logits, logits_bytes) != hipSuccess ||
        hipMalloc((void **)&d_idx, route_bytes) != hipSuccess ||
        hipMalloc((void **)&d_w, weight_bytes) != hipSuccess) {
        rc = -2;
        goto done;
    }
    if (hipMemcpyAsync(d_logits, h_logits, logits_bytes, hipMemcpyHostToDevice, r->stream) != hipSuccess) {
        rc = -2; goto done;
    }
    int ne = n_experts, K = n_used;
    void *args[] = { &d_logits, &ne, &K, &d_idx, &d_w };
    LAUNCH(r->fn_moe_topk_batch, M, 1, 1, 256, 1, 1, 0, r->stream, args);
    if (hipMemcpyAsync(h_idx, d_idx, route_bytes, hipMemcpyDeviceToHost, r->stream) != hipSuccess ||
        hipMemcpyAsync(h_w, d_w, weight_bytes, hipMemcpyDeviceToHost, r->stream) != hipSuccess ||
        hipStreamSynchronize(r->stream) != hipSuccess) {
        rc = -2; goto done;
    }
    for (int i = 0; i < M * n_used; i++) {
        if (h_idx[i] != h_ref_idx[i] || fabsf(h_w[i] - h_ref_w[i]) > 2e-5f) {
            fprintf(stderr, "routing mismatch ne=%d K=%d row=%d rank=%d: GPU %d/%.8g CPU %d/%.8g\n",
                    n_experts, n_used, i / n_used, i % n_used,
                    h_idx[i], h_w[i], h_ref_idx[i], h_ref_w[i]);
            rc = 1; break;
        }
    }

done:
    if (d_logits) hipFree(d_logits);
    if (d_idx) hipFree(d_idx);
    if (d_w) hipFree(d_w);
    free(h_logits); free(h_idx); free(h_w); free(h_ref_idx); free(h_ref_w);
    return rc;
}

/* A/B verify: GPU matvec_<type> vs caller-provided CPU dequant + scalar matvec
 * on identical raw quant bytes. Used by test_hip_llm --verify-quant-kernels. */
int hip_llm_verify_quant_matvec(
        hip_llm_runner *r, int weight_type,
        void (*cpu_dequant_row)(const void *src, float *dst, int n),
        int n_rows, int n_cols,
        double *out_rel_l2, double *out_max_abs) {
    if (!r || !cpu_dequant_row || n_rows <= 0 || n_cols <= 0) return -1;

    int blk_elems = 0, blk_bytes = 0;
    if (quant_matvec_block_info(weight_type, &blk_elems, &blk_bytes) != 0) return -1;
    if ((n_cols % blk_elems) != 0) return -1;
    int n_blk_per_row = n_cols / blk_elems;
    size_t row_bytes  = (size_t)n_blk_per_row * blk_bytes;
    size_t mat_bytes  = (size_t)n_rows * row_bytes;

    unsigned char *h_mat  = (unsigned char *)malloc(mat_bytes);
    float *h_x       = (float *)malloc((size_t)n_cols * sizeof(float));
    float *h_dst_hip = (float *)malloc((size_t)n_rows * sizeof(float));
    float *h_dst_ref = (float *)malloc((size_t)n_rows * sizeof(float));
    float *h_row_f32 = (float *)malloc((size_t)n_cols * sizeof(float));
    if (!h_mat || !h_x || !h_dst_hip || !h_dst_ref || !h_row_f32) {
        free(h_mat); free(h_x); free(h_dst_hip); free(h_dst_ref); free(h_row_f32);
        return -2;
    }

    fill_quant_matvec_inputs(h_mat, mat_bytes, h_x, n_cols, weight_type);

    void *d_mat = NULL, *d_x = NULL, *d_dst = NULL;
    if (hipMalloc(&d_mat, mat_bytes) != hipSuccess ||
        hipMalloc(&d_x,   (size_t)n_cols * sizeof(float)) != hipSuccess ||
        hipMalloc(&d_dst, (size_t)n_rows * sizeof(float)) != hipSuccess) {
        if (d_mat) hipFree(d_mat);
        if (d_x) hipFree(d_x);
        if (d_dst) hipFree(d_dst);
        free(h_mat); free(h_x); free(h_dst_hip); free(h_dst_ref); free(h_row_f32);
        return -2;
    }
    hipMemcpy(d_mat, h_mat, mat_bytes, hipMemcpyHostToDevice);
    hipMemcpy(d_x,   h_x,   (size_t)n_cols * sizeof(float), hipMemcpyHostToDevice);

    launch_matvec_auto(r, d_dst, d_mat, d_x, n_rows, n_cols, weight_type);
    hipStreamSynchronize(r->stream);
    hipMemcpy(h_dst_hip, d_dst, (size_t)n_rows * sizeof(float), hipMemcpyDeviceToHost);

    /* CPU reference. */
    for (int row = 0; row < n_rows; row++) {
        const void *row_ptr = h_mat + (size_t)row * row_bytes;
        cpu_dequant_row(row_ptr, h_row_f32, n_cols);
        double acc = 0.0;
        for (int k = 0; k < n_cols; k++) acc += (double)h_row_f32[k] * (double)h_x[k];
        h_dst_ref[row] = (float)acc;
    }

    /* Random raw bytes can include FP16 NaN/Inf in the scale field, which
     * propagates through the dequant + dot product on both sides. A row where
     * either side is non-finite is treated as "invalid input" (NaN-poisoned)
     * and skipped from the rel_l2 sum. The verifier still notices real
     * divergence on the rows that do produce finite outputs — there are
     * plenty (typically ~95%+ of rows on a 64-row sample). */
    double num = 0.0, den = 0.0, max_abs = 0.0;
    int n_valid = 0;
    for (int i = 0; i < n_rows; i++) {
        float h = h_dst_hip[i], rf = h_dst_ref[i];
        int ok = !(h != h) && !(rf != rf) &&
                 (h - h == 0.0f) && (rf - rf == 0.0f);
        if (!ok) continue;
        n_valid++;
        double diff = (double)h - (double)rf;
        double ad = diff < 0 ? -diff : diff;
        if (ad > max_abs) max_abs = ad;
        num += diff * diff;
        den += (double)rf * (double)rf;
    }
    double rel_l2 = (n_valid == 0) ? 1.0
                                   : ((den > 1e-30) ? sqrt(num / den) : sqrt(num));
    if (out_rel_l2)  *out_rel_l2 = rel_l2;
    if (out_max_abs) *out_max_abs = max_abs;

    hipFree(d_mat); hipFree(d_x); hipFree(d_dst);
    free(h_mat); free(h_x); free(h_dst_hip); free(h_dst_ref); free(h_row_f32);
    return 0;
}

int hip_llm_bench_quant_matvec(
        hip_llm_runner *r, int weight_type,
        int n_rows, int n_cols,
        int warmup, int iters,
        float *out_ms) {
    if (!r || n_rows <= 0 || n_cols <= 0 || iters <= 0 || !out_ms) return -1;

    int blk_elems = 0, blk_bytes = 0;
    if (quant_matvec_block_info(weight_type, &blk_elems, &blk_bytes) != 0) return -1;
    if ((n_cols % blk_elems) != 0) return -1;
    int n_blk_per_row = n_cols / blk_elems;
    size_t row_bytes = (size_t)n_blk_per_row * blk_bytes;
    size_t mat_bytes = (size_t)n_rows * row_bytes;
    size_t x_bytes = (size_t)n_cols * sizeof(float);
    size_t dst_bytes = (size_t)n_rows * sizeof(float);

    unsigned char *h_mat = (unsigned char *)malloc(mat_bytes);
    float *h_x = (float *)malloc(x_bytes);
    if (!h_mat || !h_x) {
        free(h_mat); free(h_x);
        return -2;
    }
    fill_quant_matvec_inputs(h_mat, mat_bytes, h_x, n_cols, weight_type);

    void *d_mat = NULL, *d_x = NULL, *d_dst = NULL;
    hipEvent_t ev_start = NULL, ev_stop = NULL;
    int rc = -2;
    if (hipMalloc(&d_mat, mat_bytes) != hipSuccess ||
        hipMalloc(&d_x,   x_bytes)   != hipSuccess ||
        hipMalloc(&d_dst, dst_bytes) != hipSuccess) {
        goto done;
    }
    if (hipMemcpy(d_mat, h_mat, mat_bytes, hipMemcpyHostToDevice) != hipSuccess ||
        hipMemcpy(d_x, h_x, x_bytes, hipMemcpyHostToDevice) != hipSuccess) {
        goto done;
    }
    if (hipEventCreate(&ev_start) != hipSuccess ||
        hipEventCreate(&ev_stop)  != hipSuccess) {
        goto done;
    }

    int prequant = weight_type == GGML_TYPE_IQ2_S && r->decode_dp4a &&
        getenv("LLM_BENCH_QMV_PREQUANT") &&
        atoi(getenv("LLM_BENCH_QMV_PREQUANT")) != 0;
    if (prequant)
        launch_quantize_q8(r, d_x, n_cols, r->d_act_q8, r->d_act_scale);

    for (int i = 0; i < warmup; i++) {
        if (prequant)
            launch_matvec_iq2_s_dp4a_prequant(r, d_dst, d_mat, r->d_act_q8,
                                              r->d_act_scale, n_rows, n_cols);
        else
            launch_matvec_auto(r, d_dst, d_mat, d_x, n_rows, n_cols, weight_type);
    }
    if (hipStreamSynchronize(r->stream) != hipSuccess) goto done;

    if (hipEventRecord(ev_start, r->stream) != hipSuccess) goto done;
    for (int i = 0; i < iters; i++) {
        if (prequant)
            launch_matvec_iq2_s_dp4a_prequant(r, d_dst, d_mat, r->d_act_q8,
                                              r->d_act_scale, n_rows, n_cols);
        else
            launch_matvec_auto(r, d_dst, d_mat, d_x, n_rows, n_cols, weight_type);
    }
    if (hipEventRecord(ev_stop, r->stream) != hipSuccess) goto done;
    if (hipEventSynchronize(ev_stop) != hipSuccess) goto done;

    float elapsed = 0.0f;
    if (hipEventElapsedTime(&elapsed, ev_start, ev_stop) != hipSuccess) goto done;
    *out_ms = elapsed / (float)iters;
    rc = 0;

done:
    if (ev_start) hipEventDestroy(ev_start);
    if (ev_stop) hipEventDestroy(ev_stop);
    if (d_mat) hipFree(d_mat);
    if (d_x) hipFree(d_x);
    if (d_dst) hipFree(d_dst);
    free(h_mat);
    free(h_x);
    return rc;
}

void hip_llm_reset_state(hip_llm_runner *r) {
    if (!r) return;

    if (qwen4_prefill_copies_drain(r)) return;
    /* Request resets are normally followed by work on r->stream.  Make the
     * previous request quiescent before clearing persistent hybrid state;
     * this is important for the batched conv path, which keeps the conv
     * history live across all rows of a tile. */
    if (r->stream) hipStreamSynchronize(r->stream);
    r->qwen4_forward_error = 0;
    r->qwen4_nextn_start = -1;
    if (r->qwen35_mtp) { r->qwen35_mtp->origin = -1; r->qwen35_mtp->verify_rows = 0; }
    r->cur_position = 0;
    if (r->qwen4_exact && r->layers) {
        for (int l=0;l<r->n_layers;++l)
            if (r->layers[l].d_index_cache)
                hipMemset(r->layers[l].d_index_cache,0,
                          (size_t)r->max_seq_len*r->indexer_dim*sizeof(uint16_t));
    }
    if (r->is_glm5next) {
        if (r->glm5next_cpu) glm5next_cpu_runtime_reset(r->glm5next_cpu);
        if (r->glm5next_kda_state_cache) {
            for (int l = 0; l < r->glm5next.n_layers_all; ++l)
                r->glm5next_kda_state_cache[l].ready = 0;
        }
        return;
    }
    hip_llm_set_decode_mode(r, 0);
    if (r->is_qwen4exp && r->layers) {
        /* Expert-cache residency changes cold/warm kernel selection, so a
         * repeated request in the same process can hash-differ from a
         * fresh-process run.  LLM_QWEN4_RESET_MOE_CACHE=1 makes every reset
         * (repeat/request) start from an empty cache for request isolation. */
        const char *reset_moe_env = getenv("LLM_QWEN4_RESET_MOE_CACHE");
        int reset_moe_cache = reset_moe_env && atoi(reset_moe_env) != 0;
        for (int l = 0; l < r->n_layers; ++l) {
            hip_layer *cl = &r->layers[l];
            if (cl->moe_prefill_score)
                memset(cl->moe_prefill_score, 0,
                       (size_t)r->n_experts * sizeof(uint32_t));
            if (!reset_moe_cache) continue;
            cl->moe_pending_slot = -1;
            cl->moe_pending_expert = -1;
            cl->moe_cache_next = 0;
            if (cl->moe_cache_ids)
                for (int s = 0; s < cl->moe_cache_slots; ++s)
                    cl->moe_cache_ids[s] = -1;
            if (cl->moe_cache_age)
                for (int s = 0; s < cl->moe_cache_slots; ++s)
                    cl->moe_cache_age[s] = 0;
            if (cl->moe_cache_freq)
                for (int s = 0; s < cl->moe_cache_slots; ++s)
                    cl->moe_cache_freq[s] = 0;
            if (cl->d_moe_cache_map)
                hipMemset(cl->d_moe_cache_map, 0xff,
                          (size_t)r->n_experts * sizeof(int));
        }
        if (reset_moe_cache) {
            r->moe_cache_clock = 0;
            /* Drain the async expert-copy pipeline so a pending upload from a
             * previous repeat cannot land in a slot that this request has
             * reassigned.  Without this the ~147-tok/s pipeline profile is not
             * request-isolated. */
            if (r->stream) hipStreamSynchronize(r->stream);
            if (r->moe_copy_stream) hipStreamSynchronize(r->moe_copy_stream);
            for (int l = 0; l < 128; ++l)
                r->moe_pipeline_valid[l] = 0;
            /* Bank metadata is rebuilt before publication on every wave.
             * Draining/resetting fences at entry is sufficient; no weight
             * memset is needed and stale contents are never addressed. */
        }
    }
    if (r->ple_n_heads > 0) {
        r->ple_history[0] = r->ple_history[1] = r->ple_eos_token;
        if (r->d_ple_conv_state) {
            size_t hist = (size_t)(r->ple_conv_kernel - 1) * r->ple_ngram;
            hipMemset(r->d_ple_conv_state, 0,
                      hist * (size_t)r->hc_count * r->n_embd * sizeof(float));
        }
    }
    if (r->is_hybrid) {
        for (int l = 0; l < r->n_layers; l++) {
            hip_layer *cl = &r->layers[l];
            if (!cl->is_ssm) continue;
            if (cl->d_conv_state) {
                size_t conv_bytes = (size_t)(r->ssm_conv_kernel - 1) * r->ssm_qkv_dim * sizeof(float);
                if (hipMemsetAsync(cl->d_conv_state, 0, conv_bytes, r->stream) != hipSuccess)
                    r->qwen4_forward_error = 1;
            }
            if (cl->d_recurrent_state) {
                size_t rec_bytes = (size_t)r->ssm_dt_rank * r->ssm_d_state * r->ssm_d_state * sizeof(float);
                if (hipMemsetAsync(cl->d_recurrent_state, 0, rec_bytes, r->stream) != hipSuccess)
                    r->qwen4_forward_error = 1;
            }
        }
    }
    /* hipMemset/hipMemsetAsync implementations differ in whether the device
     * write is ordered with a non-default stream.  Fence the reset so the
     * first batched SSM tile cannot observe a prior request's history. */
    if (r->stream) hipStreamSynchronize(r->stream);
    if (r->is_gemma4) {
        for (int l = 0; l < r->n_layers; l++) {
            hip_layer *cl = &r->layers[l];
            if (cl->shared_kv_source >= 0) continue;
            int local_kv = cl->local_kv_heads;
            int local_hd = cl->local_head_dim;
            size_t kv_bytes = (size_t)local_kv * local_hd * sizeof(float);
            if (cl->is_swa) {
                kv_bytes *= r->swa_window_size;
            } else {
                kv_bytes *= r->max_seq_len;
            }
            if (r->d_key_cache[l])   hipMemset(r->d_key_cache[l], 0, kv_bytes);
            if (r->d_value_cache[l]) hipMemset(r->d_value_cache[l], 0, kv_bytes);
        }
    }
}

struct hip_llm_state_snapshot {
    int n_layers;
    void **conv_host;
    void **rec_host;
    size_t *conv_bytes;
    size_t *rec_bytes;
    void *ple_host;
    size_t ple_bytes;
    int32_t ple_history[2];
    void **kv_key_host;
    void **kv_value_host;
    size_t *kv_bytes;
    int kv_start;
    int kv_count;
    float *hc_host, *nextn_hc_host, *logits_host;
    size_t hc_bytes, logits_bytes;
    int position, nextn_start;
    void **index_host;
    size_t index_bytes;
    void *nextn_key_host, *nextn_value_host;
    size_t nextn_kv_bytes;
};

void hip_llm_free_state_snapshot(hip_llm_state_snapshot *s) {
    if (!s) return;
    for (int l = 0; l < s->n_layers; ++l) {
        free(s->conv_host ? s->conv_host[l] : NULL);
        free(s->rec_host ? s->rec_host[l] : NULL);
    }
    free(s->conv_host);
    free(s->rec_host);
    free(s->conv_bytes);
    free(s->rec_bytes);
    free(s->ple_host);
    if (s->kv_key_host && s->kv_value_host) {
        for (int l = 0; l < s->n_layers; ++l) {
            free(s->kv_key_host[l]);
            free(s->kv_value_host[l]);
        }
    }
    free(s->kv_key_host);
    free(s->kv_value_host);
    free(s->kv_bytes);
    if(s->index_host)for(int l=0;l<s->n_layers;++l)free(s->index_host[l]);
    free(s->index_host);free(s->nextn_key_host);free(s->nextn_value_host);
    free(s->hc_host);free(s->nextn_hc_host);free(s->logits_host);
    free(s);
}

hip_llm_state_snapshot *hip_llm_snapshot_state_window(hip_llm_runner *r,
                                                       int start_pos,
                                                       int n_positions) {
    if (!r || !r->is_qwen4exp || start_pos < 0 || n_positions <= 0 ||
        start_pos + n_positions > r->max_seq_len) return NULL;
    hip_llm_state_snapshot *s = hip_llm_snapshot_state(r);
    if (!s) return NULL;
    s->kv_key_host = (void **)calloc((size_t)r->n_layers, sizeof(void *));
    s->kv_value_host = (void **)calloc((size_t)r->n_layers, sizeof(void *));
    s->kv_bytes = (size_t *)calloc((size_t)r->n_layers, sizeof(size_t));
    s->index_host = calloc((size_t)r->n_layers, sizeof(void *));
    s->index_bytes = (size_t)n_positions*r->indexer_dim*sizeof(uint16_t);
    s->kv_start = start_pos;
    s->kv_count = n_positions;
    if (!s->kv_key_host || !s->kv_value_host || !s->kv_bytes || !s->index_host) {
        hip_llm_free_state_snapshot(s); return NULL;
    }
    if (hipDeviceSynchronize() != hipSuccess) {
        hip_llm_free_state_snapshot(s); return NULL;
    }
    for (int l = 0; l < r->n_layers; ++l) {
        hip_layer *cl = &r->layers[l];
        if (cl->is_ssm || !r->d_key_cache[l] || !r->d_value_cache[l]) continue;
        if(cl->d_index_cache) {
            s->index_host[l]=malloc(s->index_bytes);
            if(!s->index_host[l] || hipMemcpy(s->index_host[l],
                (unsigned char *)cl->d_index_cache+(size_t)start_pos*r->indexer_dim*sizeof(uint16_t),
                s->index_bytes,hipMemcpyDeviceToHost)) {hip_llm_free_state_snapshot(s);return NULL;}
        }
        size_t bytes = (size_t)n_positions * (size_t)cl->local_kv_heads *
                       (size_t)cl->local_head_dim * sizeof(uint16_t);
        s->kv_key_host[l] = malloc(bytes);
        s->kv_value_host[l] = malloc(bytes);
        s->kv_bytes[l] = bytes;
        if (!s->kv_key_host[l] || !s->kv_value_host[l] ||
            hipMemcpy(s->kv_key_host[l], (unsigned char *)r->d_key_cache[l] +
                      (size_t)start_pos * bytes / (size_t)n_positions, bytes,
                      hipMemcpyDeviceToHost) != hipSuccess ||
            hipMemcpy(s->kv_value_host[l], (unsigned char *)r->d_value_cache[l] +
                      (size_t)start_pos * bytes / (size_t)n_positions, bytes,
                      hipMemcpyDeviceToHost) != hipSuccess) {
            hip_llm_free_state_snapshot(s); return NULL;
        }
    }
    if(r->qwen4_nextn_fusion_loaded) {
        size_t stride=(size_t)r->n_kv_heads*r->head_dim*sizeof(uint16_t);
        s->nextn_kv_bytes=(size_t)n_positions*stride;
        s->nextn_key_host=malloc(s->nextn_kv_bytes);s->nextn_value_host=malloc(s->nextn_kv_bytes);
        if(!s->nextn_key_host || !s->nextn_value_host ||
           hipMemcpy(s->nextn_key_host,(char *)r->d_qwen4_nextn_key_cache+start_pos*stride,s->nextn_kv_bytes,hipMemcpyDeviceToHost) ||
           hipMemcpy(s->nextn_value_host,(char *)r->d_qwen4_nextn_value_cache+start_pos*stride,s->nextn_kv_bytes,hipMemcpyDeviceToHost)) {
            hip_llm_free_state_snapshot(s);return NULL;
        }
    }
    return s;
}

hip_llm_state_snapshot *hip_llm_snapshot_state(hip_llm_runner *r) {
    if (!r) return NULL;
    hip_llm_state_snapshot *s = (hip_llm_state_snapshot *)calloc(1, sizeof(*s));
    if (!s) return NULL;
    s->n_layers = r->n_layers;
    s->conv_host = (void **)calloc((size_t)s->n_layers, sizeof(void *));
    s->rec_host = (void **)calloc((size_t)s->n_layers, sizeof(void *));
    s->conv_bytes = (size_t *)calloc((size_t)s->n_layers, sizeof(size_t));
    s->rec_bytes = (size_t *)calloc((size_t)s->n_layers, sizeof(size_t));
    if (!s->conv_host || !s->rec_host || !s->conv_bytes || !s->rec_bytes)
        goto fail;
    if (hipDeviceSynchronize() != hipSuccess) goto fail;
    s->position=r->cur_position;
    s->nextn_start=r->qwen4_nextn_start;
    if(r->is_qwen4exp) {
        s->hc_bytes=(size_t)r->hc_count*r->n_embd*sizeof(float);
        s->logits_bytes=(size_t)r->n_vocab*sizeof(float);
        s->hc_host=malloc(s->hc_bytes);s->logits_host=malloc(s->logits_bytes);
        if(!s->hc_host || !s->logits_host ||
           hipMemcpy(s->hc_host,r->d_hc,s->hc_bytes,hipMemcpyDeviceToHost) ||
           hipMemcpy(s->logits_host,r->d_logits,s->logits_bytes,hipMemcpyDeviceToHost))goto fail;
        if(r->qwen4_nextn_fusion_loaded) {
            s->nextn_hc_host=malloc(s->hc_bytes);
            if(!s->nextn_hc_host || hipMemcpy(s->nextn_hc_host,r->d_qwen4_nextn_hc,s->hc_bytes,hipMemcpyDeviceToHost))goto fail;
        }
    }
    for (int l = 0; l < r->n_layers; ++l) {
        hip_layer *cl = &r->layers[l];
        if (!cl->is_ssm) continue;
        if (cl->d_conv_state) {
            s->conv_bytes[l] = (size_t)(r->ssm_conv_kernel - 1) *
                               r->ssm_qkv_dim * sizeof(float);
            s->conv_host[l] = malloc(s->conv_bytes[l]);
            if (!s->conv_host[l] || hipMemcpy(s->conv_host[l], cl->d_conv_state,
                                              s->conv_bytes[l], hipMemcpyDeviceToHost) != hipSuccess)
                goto fail;
        }
        if (cl->d_recurrent_state) {
            s->rec_bytes[l] = (size_t)r->ssm_dt_rank * r->ssm_d_state *
                              r->ssm_d_state * sizeof(float);
            s->rec_host[l] = malloc(s->rec_bytes[l]);
            if (!s->rec_host[l] || hipMemcpy(s->rec_host[l], cl->d_recurrent_state,
                                             s->rec_bytes[l], hipMemcpyDeviceToHost) != hipSuccess)
                goto fail;
        }
    }
    if (r->d_ple_conv_state && r->ple_n_heads > 0) {
        size_t hist = (size_t)(r->ple_conv_kernel - 1) * r->ple_ngram;
        s->ple_bytes = hist * (size_t)r->hc_count * r->n_embd * sizeof(float);
        s->ple_host = malloc(s->ple_bytes);
        if (!s->ple_host || hipMemcpy(s->ple_host, r->d_ple_conv_state,
                                      s->ple_bytes, hipMemcpyDeviceToHost) != hipSuccess)
            goto fail;
        s->ple_history[0] = r->ple_history[0];
        s->ple_history[1] = r->ple_history[1];
    }
    return s;
fail:
    hip_llm_free_state_snapshot(s);
    return NULL;
}

int hip_llm_restore_state(hip_llm_runner *r, const hip_llm_state_snapshot *s) {
    if (!r || !s || s->n_layers != r->n_layers) return -1;
    hip_llm_set_decode_mode(r, 0);
    if(hipStreamSynchronize(r->stream))return -1;
    if(s->hc_host && (hipMemcpy(r->d_hc,s->hc_host,s->hc_bytes,hipMemcpyHostToDevice) ||
       hipMemcpy(r->d_logits,s->logits_host,s->logits_bytes,hipMemcpyHostToDevice)))return -1;
    if(s->logits_host)memcpy(r->h_output,s->logits_host,s->logits_bytes);
    if(s->nextn_hc_host && (!r->d_qwen4_nextn_hc ||
       hipMemcpy(r->d_qwen4_nextn_hc,s->nextn_hc_host,s->hc_bytes,hipMemcpyHostToDevice)))return -1;
    r->cur_position=s->position;r->qwen4_nextn_start=s->nextn_start;
    if(hipMemcpy(r->d_position,&s->position,sizeof(int),hipMemcpyHostToDevice))return -1;
    for (int l = 0; l < r->n_layers; ++l) {
        hip_layer *cl = &r->layers[l];
        if (s->conv_host[l] && cl->d_conv_state &&
            hipMemcpy(cl->d_conv_state, s->conv_host[l], s->conv_bytes[l], hipMemcpyHostToDevice) != hipSuccess)
            return -1;
        if (s->rec_host[l] && cl->d_recurrent_state &&
            hipMemcpy(cl->d_recurrent_state, s->rec_host[l], s->rec_bytes[l], hipMemcpyHostToDevice) != hipSuccess)
            return -1;
    }
    if (s->ple_host && r->d_ple_conv_state &&
        hipMemcpy(r->d_ple_conv_state, s->ple_host, s->ple_bytes, hipMemcpyHostToDevice) != hipSuccess)
        return -1;
    if (s->kv_key_host && s->kv_value_host) {
        for (int l = 0; l < r->n_layers; ++l) {
            if (!s->kv_key_host[l] || !r->d_key_cache[l]) continue;
            hip_layer *cl = &r->layers[l];
            size_t stride = (size_t)cl->local_kv_heads * cl->local_head_dim * sizeof(uint16_t);
            unsigned char *key = (unsigned char *)r->d_key_cache[l] +
                                 (size_t)s->kv_start * stride;
            unsigned char *value = (unsigned char *)r->d_value_cache[l] +
                                   (size_t)s->kv_start * stride;
            if (hipMemcpy(key, s->kv_key_host[l], s->kv_bytes[l], hipMemcpyHostToDevice) != hipSuccess ||
                hipMemcpy(value, s->kv_value_host[l], s->kv_bytes[l], hipMemcpyHostToDevice) != hipSuccess)
                return -1;
        }
    }
    r->ple_history[0] = s->ple_history[0];
    r->ple_history[1] = s->ple_history[1];
    if(s->index_host)for(int l=0;l<r->n_layers;++l) {
        if(s->index_host[l] && (!r->layers[l].d_index_cache || hipMemcpy(
            (char *)r->layers[l].d_index_cache+(size_t)s->kv_start*r->indexer_dim*sizeof(uint16_t),
            s->index_host[l],s->index_bytes,hipMemcpyHostToDevice)))return -1;
    }
    if(s->nextn_key_host) {
        size_t stride=(size_t)r->n_kv_heads*r->head_dim*sizeof(uint16_t);
        if(!r->qwen4_nextn_fusion_loaded ||
           hipMemcpy((char *)r->d_qwen4_nextn_key_cache+s->kv_start*stride,s->nextn_key_host,s->nextn_kv_bytes,hipMemcpyHostToDevice) ||
           hipMemcpy((char *)r->d_qwen4_nextn_value_cache+s->kv_start*stride,s->nextn_value_host,s->nextn_kv_bytes,hipMemcpyHostToDevice))return -1;
    }
    return hipDeviceSynchronize() == hipSuccess ? 0 : -1;
}

void hip_llm_set_decode_mode(hip_llm_runner *r, int enabled) {
    if (!r) return;

    if (qwen4_prefill_copies_drain(r)) return;
    if (!enabled && r->moe_copy_stream) {
        /* Prefill may immediately reuse cache slots. Complete pending decode
         * copies and publish their host identities before it does so. */
        hipStreamSynchronize(r->moe_copy_stream);
        for (int l = 0; r->layers && l < r->n_layers; ++l) {
            hip_layer *cl = &r->layers[l];
            if (cl->moe_cache_ids && cl->moe_pending_slot >= 0) {
                cl->moe_cache_ids[cl->moe_pending_slot] = cl->moe_pending_expert;
                cl->moe_pending_slot = -1;
                cl->moe_pending_expert = -1;
            }
        }
    }
    if (enabled && r->is_qwen4exp && r->layers) {
        /* Normal batched prefill uses direct cache pointers and defers the
         * device map writes.  Publish one coherent map per layer before the
         * first decode kernel instead of issuing two tiny H2D copies for
         * every prefill miss. */
        if (r->moe_copy_stream) hipStreamSynchronize(r->moe_copy_stream);
        for (int l = 0; l < r->n_layers; ++l) {
            hip_layer *cl = &r->layers[l];
            if (!cl->d_moe_cache_map || !cl->moe_cache_ids) continue;
            int *map = (int *)malloc((size_t)r->n_experts * sizeof(int));
            if (!map) continue;
            for (int e = 0; e < r->n_experts; ++e) map[e] = -1;
            for (int s = 0; s < cl->moe_cache_slots; ++s) {
                int e = cl->moe_cache_ids[s];
                if (e >= 0 && e < r->n_experts) map[e] = s;
            }
            hipError_t copy_err = hipMemcpyAsync(cl->d_moe_cache_map, map,
                           (size_t)r->n_experts * sizeof(int),
                           hipMemcpyHostToDevice, r->stream);
            hipError_t sync_err = hipStreamSynchronize(r->stream);
            free(map);
            if (copy_err != hipSuccess || sync_err != hipSuccess) {
                r->qwen4_forward_error = 1;
                return;
            }
        }
        hipStreamSynchronize(r->stream);
    }
    r->decode_mode = enabled != 0;
}

int hip_llm_n_embd(const hip_llm_runner *r) { return r ? r->n_embd : 0; }
int hip_llm_n_layers(const hip_llm_runner *r) { return r ? r->n_layers : 0; }
int hip_llm_n_vocab(const hip_llm_runner *r) { return r ? r->n_vocab : 0; }
int hip_llm_max_seq_len(const hip_llm_runner *r) { return r ? r->max_seq_len : 0; }

int hip_llm_get_moe_stats(const hip_llm_runner *r, hip_llm_moe_stats *stats) {
    if (!r || !stats) return -1;
    *stats = r->moe_stats;
    stats->cache_hits += r->glm5next_moe_cache_hits;
    stats->cache_misses += r->glm5next_moe_cache_misses;
    if (getenv("LLM_MOE_LAYER_STATS")) {
        for (int l = 0; l < r->n_layers && l < 128; ++l) {
            uint64_t h = r->moe_layer_hits[l], m = r->moe_layer_misses[l];
            if (h + m)
                fprintf(stderr, "hip_llm: MoE layer=%d slots=%d hit=%llu miss=%llu rate=%.1f%%\n",
                        l, r->layers[l].moe_cache_slots,
                        (unsigned long long)h, (unsigned long long)m,
                        100.0 * (double)h / (double)(h + m));
        }
    }
    return 0;
}

int hip_llm_get_vram_stats(const hip_llm_runner *r, hip_llm_vram_stats *stats) {
    if (!r || !stats || stats->struct_size < sizeof(*stats)) return -1;
    size_t free_b = 0, total_b = 0;
    if (hipMemGetInfo(&free_b, &total_b) != hipSuccess || total_b == 0) return -1;
    stats->total_bytes = total_b;
    stats->free_bytes = free_b;
    stats->peak_used_bytes = r->vram_peak_used_bytes;
    return 0;
}

void hip_llm_reset_moe_stats(hip_llm_runner *r) {
    if (r) {
        memset(&r->moe_stats, 0, sizeof(r->moe_stats));
        r->glm5next_moe_cache_hits = 0;
        r->glm5next_moe_cache_misses = 0;
        memset(r->moe_layer_hits, 0, sizeof(r->moe_layer_hits));
        memset(r->moe_layer_misses, 0, sizeof(r->moe_layer_misses));
    }
}
